    top uut (
        .clk(clk),
        .rst_n(rst_n),
        .in_valid(in_valid),
        .in_data(in_data),
        .sum(sum)
    );

    always #5 clk = ~clk;

    integer i;
    reg [7:0] test_data [0:4];
    reg [7:0] expected_sums [0:4];
    integer timeout;
    integer passed;

    initial begin
        clk = 0;
        rst_n = 0;
        in_valid = 0;
        in_data = 0;
