        expected_sums[3] = 8'd100;
        expected_sums[4] = 8'd150;

        repeat (5) @(negedge clk);
        rst_n = 1;
        repeat (2) @(negedge clk);

        for (i = 0; i < 5; i = i + 1) begin
            @(negedge clk);
