module tb_top;
  reg clk;
  reg reset_n;
  reg in_valid;
  reg [7:0] in_data;
  wire in_ready;
  wire out0_valid;
  wire [7:0] out0_data;
  reg out0_ready;
  wire out1_valid;
  wire [7:0] out1_data;
  reg out1_ready;

  top uut (
    .clk(clk),
    .reset_n(reset_n),
