module accumulator_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    input wire [DATA_WIDTH-1:0] sample,
    output wire sample_ready,
    output wire [DATA_WIDTH-1:0] sum
);
    reg [DATA_WIDTH-1:0] accumulated_sum;
    reg                  sample_ready_reg;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        accumulated_sum <= 0;
        sample_ready_reg <= 0;
      end else begin
        sample_ready_reg <= 1;                       // always ready after reset
        if (sample_valid && sample_ready_reg) begin
          accumulated_sum <= accumulated_sum + sample; // wraps on 8‑bit overflow
        end
      end
    end

    assign sample_ready = sample_ready_reg;
    assign sum          = accumulated_sum;
endmodule

module skid_buffer #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
    reg stored_valid;
    reg [DATA_WIDTH-1:0] stored_data;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        stored_valid <= 0;
        stored_data  <= 0;
      end else begin
        if (out_ready) begin
          stored_valid <= 0;   // consumed
        end
        if (in_valid && (out_ready || !stored_valid)) begin
          stored_data  <= in_data;
          stored_valid <= 1;
        end
      end
    end

    assign in_ready  = out_ready || !stored_valid;
    assign out_valid = stored_valid;
    assign out_data  = stored_data;
endmodule

module top (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [7:0] in_data,
    output wire in_ready,
