`timescale 1ns / 1ps

module skid_buffer #(
    parameter WIDTH = 8
) (
    input  wire        clk,
    input  wire        nreset,
    input  wire        in_valid,
    input  wire [WIDTH-1:0] in_data,
    output wire        in_ready,
    output wire        out_valid,
    output wire [WIDTH-1:0] out_data,
    input  wire        out_ready
);

    reg        valid_r;
    reg [WIDTH-1:0] data_r;

    // Output combinational logic
    assign out_valid = valid_r || in_valid;
    assign out_data  = valid_r ? data_r : in_data;
    assign in_ready  = !valid_r || out_ready;

    // Register logic
    always @(posedge clk or negedge nreset) begin
        if (!nreset) begin
            valid_r <= 1'b0;
            data_r  <= {WIDTH{1'b0}};
        end else begin
            if (in_ready && in_valid) begin
                if (!out_ready) begin
                    // stash incoming data
                    valid_r <= 1'b1;
                    data_r  <= in_data;
                end else begin
                    // pass through, no stash needed
                    valid_r <= 1'b0;
                end
            end else if (valid_r && out_ready) begin
                // stash consumed, no new data
                valid_r <= 1'b0;
            end
            // otherwise no change
        end
    end

endmodule

`timescale 1ns / 1ps

module stream_fork #(
    parameter WIDTH = 8
) (
    input  wire        clk,
    input  wire        nreset,
    input  wire        in_valid,
    input  wire [WIDTH-1:0] in_data,
    output wire        in_ready,
    output wire        out0_valid,
    output wire [WIDTH-1:0] out0_data,
    input  wire        out0_ready,
    output wire        out1_valid,
    output wire [WIDTH-1:0] out1_data,
    input  wire        out1_ready
);

    // Fork only proceeds when both outputs are ready
    assign in_ready = out0_ready & out1_ready;

    // Valid outputs are active only when both sides are ready and input is valid
    wire fork_enable = in_valid & out0_ready & out1_ready;
    assign out0_valid = fork_enable;
    assign out1_valid = fork_enable;

    // Data duplication
    assign out0_data = in_data;
    assign out1_data = in_data;

endmodule

`timescale 1ns / 1ps

module stream_stage #(
    parameter WIDTH = 8
) (
    input  wire        clk,
    input  wire        nreset,
    input  wire        in_valid,
    input  wire [WIDTH-1:0] in_data,
    output wire        in_ready,
    output wire        out_valid,
    output reg  [WIDTH-1:0] out_data,
    input  wire        out_ready
);

    reg out_valid_r;

    assign out_valid = out_valid_r;
    assign in_ready  = out_ready || !out_valid_r;

    always @(posedge clk or negedge nreset) begin
        if (!nreset) begin
            out_valid_r <= 1'b0;
            out_data     <= {WIDTH{1'b0}};
        end else begin
            if (out_ready || !out_valid_r) begin
                out_valid_r <= in_valid;
                out_data     <= in_data;
            end
        end
    end

endmodule

`timescale 1ns / 1ps

module top (
    input  wire        clk,
    input  wire        nreset,
    input  wire        in_valid,
    input  wire [7:0]  in_data,
    output wire        in_ready,
    output wire        out0_valid,
    output wire [7:0]  out0_data,
    input  wire        out0_ready,
    output wire        out1_valid,
    output wire [7:0]  out1_data,
    input  wire        out1_ready
);

    // Internal connections
    wire        skid_out_valid;
    wire [7:0]  skid_out_data;
    wire        skid_out_ready;

    wire        fork_out0_valid;
    wire [7:0]  fork_out0_data;
    wire        fork_out0_ready;
    wire        fork_out1_valid;
    wire [7:0]  fork_out1_data;
    wire        fork_out1_ready;

    // Skid buffer
    skid_buffer #(
        .WIDTH(8)
    ) u_skid (
        .clk      (clk),
        .nreset   (nreset),
        .in_valid (in_valid),
        .in_data  (in_data),
        .in_ready (in_ready),
        .out_valid(skid_out_valid),
        .out_data (skid_out_data),
        .out_ready(skid_out_ready)
    );

    // Stream fork
    stream_fork #(
        .WIDTH(8)
    ) u_fork (
        .clk      (clk),
        .nreset   (nreset),
        .in_valid (skid_out_valid),
        .in_data  (skid_out_data),
        .in_ready (skid_out_ready),
        .out0_valid(fork_out0_valid),
        .out0_data (fork_out0_data),
        .out0_ready(fork_out0_ready),
        .out1_valid(fork_out1_valid),
        .out1_data (fork_out1_data),
        .out1_ready(fork_out1_ready)
    );

    // Output stage 0
    stream_stage #(
        .WIDTH(8)
    ) u_stage0 (
        .clk      (clk),
        .nreset   (nreset),
        .in_valid (fork_out0_valid),
        .in_data  (fork_out0_data),
        .in_ready (fork_out0_ready),
        .out_valid(out0_valid),
        .out_data (out0_data),
        .out_ready(out0_ready)
    );

    // Output stage 1
    stream_stage #(
        .WIDTH(8)
    ) u_stage1 (
        .clk      (clk),
        .nreset   (nreset),
        .in_valid (fork_out1_valid),
        .in_data  (fork_out1_data),
        .in_ready (fork_out1_ready),
        .out_valid(out1_valid),
