// accumulator_core.v: accumulates samples and outputs running sum with handshaking
module accumulator_core (
    input clk,
    input rst_n,
    input       sample_valid,
    input [7:0] sample,
    output reg  sample_ready,
    output      out_valid,
    output [7:0] sum,
    input       out_ready
);

reg [7:0] sum_reg;
reg       has_valid;  // flag: output register holds a valid sum waiting to be taken

// sample_ready: we can accept a new sample when we are not busy with an output, or if downstream is ready to take the current output simultaneously
// i.e. we are empty (ready for new sample) or we can accept a new sample at the same time the current output is consumed
wire sample_accept_allowed = !has_valid || out_ready;

always @* begin
    sample_ready = sample_accept_allowed;
end

// output valid and sum logic
assign out_valid = has_valid;
assign sum       = sum_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg  <= 8'd0;
        has_valid <= 1'b0;
    end else begin
        if (has_valid && out_ready) begin
            // current sum output is being consumed
            if (sample_valid && sample_ready) begin
                // simultaneously accept new sample and output old sum; update sum_reg with new addition
                sum_reg <= sum_reg + sample;
                // keep has_valid high to output the new sum in the next cycle
                has_valid <= 1'b1;
            end else begin
                // no new sample, become empty
                has_valid <= 1'b0;
                // sum_reg remains unchanged
            end
        end else if (!has_valid && sample_valid && sample_ready) begin
            // accept new sample and immediately prepare to output updated sum
            sum_reg <= sum_reg + sample;
            has_valid <= 1'b1;
        end else begin
            // either has_valid=1 but out_ready=0, or has_valid=0 and no sample, so hold state
            if (has_valid) begin
                // still waiting for out_ready, keep sum_reg and has_valid
            end
            // no change
        end
    end
end

endmodule

// skid_buffer.v: standard skid buffer for back-pressured pipelines
module skid_buffer (
    input clk,
    input rst_n,
    input       in_valid,
    input [7:0] in_data,
    output      in_ready,
    output reg  out_valid,
    output reg [7:0] out_data,
    input       out_ready
);

reg        full;   // 1 indicates output register holds valid data
reg [7:0]  storage;

// in_ready is high when the buffer can accept a new word
assign in_ready = !full || out_ready;

// out_valid is high when the output register holds valid data
// already registered as out_valid

// out_data is driven by out_data register

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        full <= 1'b0;
        out_data <= 8'd0;
        out_valid <= 1'b0;
    end else begin
        if (full) begin
            // we have stored data
            if (out_ready) begin
                // output data is being taken
                if (in_valid && in_ready) begin
                    // accept new data and replace
                    out_data <= in_data;
                    full <= 1'b1;
                end else begin
                    // no new data, go empty
                    full <= 1'b0;
                    out_data <= out_data; // keep previous data until overwritten
                end
                // out_valid goes low only if we become empty and no new data is arriving
                out_valid <= in_valid && in_ready;
            end else begin
                // output not ready, keep full and data stable
                // can we accept new data? in_ready = !full || out_ready = 0, so no
                // do nothing
                out_valid <= 1'b1;
            end
        end else begin
            // buffer empty
            if (in_valid) begin
                // accept incoming data
                out_data <= in_data;
                full <= 1'b1;
                out_valid <= 1'b1;
            end else begin
                out_valid <= 1'b0;
                full <= 1'b0;
            end
        end
    end
end

endmodule

// stream_join.v: synchronizes two valid/ready streams and outputs their sum
module stream_join (
    input clk,
    input rst_n,
    input       in0_valid,
    input [7:0] in0_data,
    output      in0_ready,
    input       in1_valid,
    input [7:0] in1_data,
    output      in1_ready,
    output reg  out_valid,
    output reg [7:0] out_data,
    input       out_ready
);

// internal storage for each input when it arrives before the other
reg        has_i0, has_i1;
reg [7:0]  stored_i0, stored_i1;

// ready = can accept new data for this input when we don't already have stored data
assign in0_ready = !has_i0;
assign in1_ready = !has_i1;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        has_i0   <= 1'b0;
        has_i1   <= 1'b0;
        stored_i0 <= 8'd0;
        stored_i1 <= 8'd0;
        out_valid <= 1'b0;
        out_data  <= 8'd0;
    end else begin
        // capture incoming data when valid and ready
        if (in0_valid && in0_ready) begin
            has_i0 <= 1'b1;
            stored_i0 <= in0_data;
        end else if (has_i0 && out_valid && out_ready) begin
            // consumed, clear has_i0 only if both present and handshake
            // but we only clear when a valid output handshake occurs, handled below
        end

        if (in1_valid && in1_ready) begin
            has_i1 <= 1'b1;
            stored_i1 <= in1_data;
        end

        // output handshake: if both inputs are present and output ready, output sum and clear stored flags
        if (out_valid && out_ready) begin
            // clear flags
            has_i0 <= 1'b0;
            has_i1 <= 1'b0;
            out_valid <= 1'b0;
        end

        // determine if we can produce output
        if (!out_valid || out_ready) begin
            // we can potentially produce a new output if both inputs are available
            if (has_i0 && has_i1) begin
                out_valid <= 1'b1;
                out_data  <= stored_i0 + stored_i1;
                // flags will be cleared on the next cycle's handshake
            end else begin
                // not yet both available, if we weren't already outputting, stay low
                // if we were outputting and out_ready but no new data, out_valid goes low (handled above)
            end
        end

        // special case: simultaneous arrival of new data and clearance
        if (in0_valid && in0_ready) begin
            // if this occurs while output handshake is happening, we need to update stored data
            // but the clone above to set has_i0 and stored_i0 will overwrite any earlier assignment,
            // which is what we want (latest assignment wins in same block). OK.
        end
    end
end

endmodule

// stream_stage.v: a single pipeline stage with valid/ready handshake
module stream_stage (
    input clk,
    input rst_n,
    input       in_valid,
    input [7:0] in_data,
    output      in_ready,
    output reg  out_valid,
    output reg [7:0] out_data,
    input       out_ready
);

reg       full;   // 1 if output register holds valid data
reg [7:0] storage;

// in_ready: we can accept new data if we are empty, or if we are full but downstream is ready (so we can replace stored data in the same cycle)
assign in_ready = !full || out_ready;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        full      <= 1'b0;
        storage   <= 8'd0;
        out_valid <= 1'b0;
        out_data  <= 8'd0;
    end else begin
        if (full) begin
            // we have data to output
            if (out_ready) begin
                // downstream is reading our data
                if (in_valid && in_ready) begin
                    // accept new data and update output
                    storage  <= in_data;
                    full     <= 1'b1;  // stay full
                    out_data <= in_data;
                end else begin
                    // no new data, go empty
                    full     <= 1'b0;
                end
                // out_valid: stays high only if new data arrived; else low
                out_valid <= in_valid && in_ready;
            end else begin
                // out_ready low, hold data
                // cannot accept new input because in_ready = !full || out_ready = 0
                out_valid <= 1'b1;
            end
        end else begin
            // empty
            if (in_valid) begin
                // accept new data
                storage   <= in_data;
                full      <= 1'b1;
                out_data  <= in_data;
                out_valid <= 1'b1;
            end else begin
                out_valid <= 1'b0;
                full      <= 1'b0;
            end
        end
    end
end

endmodule

