module skid_buffer #(parameter DATA_WIDTH = 0) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
    // Two-entry skid buffer
    reg out_valid_reg;
    reg [DATA_WIDTH-1:0] out_data_reg;
    reg buffer_full;
    reg [DATA_WIDTH-1:0] buffer_data;

    assign out_valid = out_valid_reg;
    assign out_data = out_data_reg;
    assign in_ready = !buffer_full;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        out_valid_reg <= 1'b0;
        buffer_full <= 1'b0;
      end else begin
        if (out_ready || !out_valid_reg) begin
          if (buffer_full) begin
            out_data_reg <= buffer_data;
            out_valid_reg <= 1'b1;
            buffer_full <= 1'b0;
          end else if (in_valid && !buffer_full) begin
            out_data_reg <= in_data;
            out_valid_reg <= 1'b1;
          end else begin
            out_valid_reg <= 1'b0;
          end
        end else begin
          if (in_valid && !buffer_full) begin
            buffer_data <= in_data;
            buffer_full <= 1'b1;
          end
        end
      end
    end
endmodule

module stream_join #(parameter DATA_WIDTH = 0) (
    input wire clk,
    input wire rst_n,
    input wire in0_valid,
    input wire [DATA_WIDTH-1:0] in0_data,
    output wire in0_ready,
    input wire in1_valid,
    input wire [DATA_WIDTH-1:0] in1_data,
    output wire in1_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
    localparam [1:0] IDLE = 2'd0;
    localparam [1:0] WAIT = 2'd1;
    localparam [1:0] JOINED = 2'd2;

    reg [1:0] state, next_state;
    reg [DATA_WIDTH-1:0] joined_data;

    assign in0_ready = (state == WAIT) && in0_valid && in1_valid;
    assign in1_ready = in0_ready;
    assign out_valid = (state == JOINED);
    assign out_data = joined_data;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        state <= IDLE;
        joined_data <= {DATA_WIDTH{1'b0}};
      end else begin
        state <= next_state;
        if (state == WAIT && in0_valid && in1_valid)
          joined_data <= in0_data;
      end
    end

    always @* begin
      next_state = state;
      case (state)
        IDLE: if (in0_valid || in1_valid) next_state = WAIT;
        WAIT: if (in0_valid && in1_valid) next_state = JOINED;
        JOINED: if (out_ready) next_state = IDLE;
        default: next_state = IDLE;
      endcase
    end
  localparam IDLE = 0;
  localparam WAIT = 0;
  localparam JOINED = 0;
endmodule

module stream_stage #(parameter DATA_WIDTH = 0) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
    // Single-register pipeline stage
    reg out_valid_reg;
    reg [DATA_WIDTH-1:0] out_data_reg;

    assign out_valid = out_valid_reg;
    assign out_data = out_data_reg;
    assign in_ready = !out_valid_reg || out_ready;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        out_valid_reg <= 1'b0;
      end else begin
        if (in_ready && in_valid) begin
          out_data_reg <= in_data;
          out_valid_reg <= 1'b1;
        end else if (out_ready && out_valid_reg) begin
          if (!(in_ready && in_valid))
            out_valid_reg <= 1'b0;
        end
      end
    end
endmodule

