            out_data_r  <= out_data_buf;
            out_valid_buf <= 1'b0;
          end else begin
            out_valid_r <= 1'b0;
          end
        end
        // input handshake
        if (in_valid && in_ready) begin
          if (!out_valid_r) begin
            out_valid_r <= 1'b1;
            out_data_r  <= in_data;
          end else begin
            out_valid_buf <= 1'b1;
            out_data_buf  <= in_data;
          end
        end
      end
