module accumulator_core (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        sample_valid,
  input  wire [7:0]  sample_data,
  output wire        sample_ready,
  output wire [7:0]  sum,
  output wire        out_valid,
  input  wire        out_ready
);

  reg [7:0]  sum_reg;
  reg        valid_reg;

  // We can accept a new sample only when downstream is ready (output will be consumed)
  assign sample_ready = out_ready;

  assign sum       = sum_reg;
  assign out_valid = valid_reg;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      sum_reg   <= 0;
      valid_reg <= 1'b0;
    end else begin
      if (sample_valid & sample_ready) begin
        sum_reg   <= sum_reg + sample_data;
        valid_reg <= 1'b1;
      end else if (out_ready & valid_reg) begin
        // If no new sample, clear valid on output handshake
        valid_reg <= 1'b0;
      end
    end
  end

endmodule

module skid_buffer (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        in_valid,
  input  wire [7:0]  in_data,
  output wire        in_ready,
  output wire        out_valid,
  output wire [7:0]  out_data,
  input  wire        out_ready
);

  reg         valid_reg;
  reg  [7:0]  data_reg;

  // in_ready: we can accept new data if downstream ready or we have no valid data stored
  assign in_ready = out_ready || !valid_reg;

  // out_valid: either we have stored data or new data is available (bypass)
  assign out_valid = valid_reg || in_valid;

  // out_data: select stored or bypass
  assign out_data = valid_reg ? data_reg : in_data;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      valid_reg <= 1'b0;
    end else begin
      // consume stored data when downstream ready and we are not bypassing new
      if (out_ready && valid_reg)
        valid_reg <= 1'b0;

      // store new data if it can not be bypassed
      if (in_valid && in_ready) begin
        if (out_ready && !valid_reg) begin
          // bypass: data passes straight to output, nothing to store
        end else begin
          data_reg  <= in_data;
          valid_reg <= 1'b1;
        end
      end
    end
  end

endmodule

module stream_join (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        in0_valid,
  input  wire [7:0]  in0_data,
  output wire        in0_ready,
  input  wire        in1_valid,
  input  wire [7:0]  in1_data,
  output wire        in1_ready,
  output wire        out_valid,
  output wire [7:0]  out_data,
  input  wire        out_ready
);

  // Join: output valid only when both inputs are valid
  assign out_valid = in0_valid & in1_valid;

  // Sum the two data streams
  assign out_data = in0_data + in1_data;

  // Ready to accept both inputs when downstream ready and both inputs valid
  wire both_valid = in0_valid & in1_valid;
  assign in0_ready = out_ready & both_valid;
  assign in1_ready = out_ready & both_valid;

endmodule

module stream_stage (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        in_valid,
  input  wire [7:0]  in_data,
  output wire        in_ready,
  output wire        out_valid,
  output wire [7:0]  out_data,
  input  wire        out_ready
);

  reg [7:0]  data_reg;
  reg        valid_reg;

  // we can accept if downstream ready or we have no valid data
  assign in_ready = out_ready || !valid_reg;

  assign out_valid = valid_reg;
  assign out_data  = data_reg;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      valid_reg <= 1'b0;
    end else begin
      if (in_valid & in_ready) begin
        data_reg  <= in_data;
        valid_reg <= 1'b1;
      end else if (out_ready) begin
        // if output handshake without new input, clear valid
        valid_reg <= 1'b0;
      end
    end
  end

endmodule

module top (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        in0_valid,
  input  wire [7:0]  in0_data,
  output wire        in0_ready,
  input  wire        in1_valid,
  input  wire [7:0]  in1_data,
  output wire        in1_ready,
  output wire        out_valid,
  output wire [7:0]  out_data
);

  // internal wires
  wire        skid0_out_valid, skid1_out_valid;
  wire [7:0]  skid0_out_data, skid1_out_data;
  wire        skid0_out_ready, skid1_out_ready;

  wire        join_out_valid;
  wire [7:0]  join_out_data;
  wire        join_out_ready;

  wire        acc_sample_ready;
  wire        acc_out_valid;
  wire [7:0]  acc_sum;
  wire        acc_out_ready;

  // skid_buffer for stream 0
  skid_buffer skid0 (
    .clk        (clk),
    .rst_n      (rst_n),
    .in_valid   (in0_valid),
    .in_data    (in0_data),
    .in_ready   (in0_ready),
    .out_valid  (skid0_out_valid),
    .out_data   (skid0_out_data),
    .out_ready  (skid0_out_ready)
  );

  // skid_buffer for stream 1
  skid_buffer skid1 (
    .clk        (clk),
    .rst_n      (rst_n),
    .in_valid   (in1_valid),
    .in_data    (in1_data),
    .in_ready   (in1_ready),
    .out_valid  (skid1_out_valid),
    .out_data   (skid1_out_data),
    .out_ready  (skid1_out_ready)
  );

  // stream_join (join two streams and add)
  stream_join join (
    .clk        (clk),
    .rst_n      (rst_n),
    .in0_valid  (skid0_out_valid),
    .in0_data   (skid0_out_data),
    .in0_ready  (skid0_out_ready),
    .in1_valid  (skid1_out_valid),
    .in1_data   (skid1_out_data),
    .in1_ready  (skid1_out_ready),
    .out_valid  (join_out_valid),
    .out_data   (join_out_data),
    .out_ready  (join_out_ready)
  );

  // accumulator_core
  accumulator_core acc (
    .clk            (clk),
    .rst_n          (rst_n),
    .sample_valid   (join_out_valid),
    .sample_data    (join_out_data),
    .sample_ready   (join_out_ready),
    .out_valid      (acc_out_valid),
    .sum            (acc_sum),
    .out_ready      (acc_out_ready)
  );

  // stream_stage (final pipeline stage)
  stream_stage stage (
    .clk        (clk),
