module accumulator_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    output wire sample_ready,
    input wire [DATA_WIDTH-1:0] sample,
    output wire [DATA_WIDTH-1:0] sum
);
    reg [DATA_WIDTH-1:0] sum_reg;
    assign sum = sample_valid ? (sum_reg + sample) : sum_reg;
    assign sample_ready = 1'b1;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        sum_reg <= 0;
      end else if (sample_valid && sample_ready) begin
        sum_reg <= sum_reg + sample;
      end
    end
endmodule

module skid_buffer #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
    reg [DATA_WIDTH-1:0] data_reg;
    reg valid_reg;
    reg [DATA_WIDTH-1:0] skid_data;
    reg skid_valid;

    assign out_data = valid_reg ? data_reg : skid_data;
    assign out_valid = valid_reg || skid_valid;
    assign in_ready = !(valid_reg && skid_valid);

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        valid_reg <= 1'b0;
        skid_valid <= 1'b0;
      end else begin
        if (out_ready) begin
          if (skid_valid) begin
            valid_reg <= 1'b1;
            data_reg <= skid_data;
            skid_valid <= 1'b0;
          end else begin
            valid_reg <= 1'b0;
          end
        end
        if (in_valid && in_ready) begin
          if (valid_reg && !skid_valid) begin
            skid_valid <= 1'b1;
            skid_data <= in_data;
          end else if (!valid_reg) begin
            valid_reg <= 1'b1;
            data_reg <= in_data;
          end
        end
      end
    end
endmodule

module stream_join #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in0_valid,
    output wire in0_ready,
    input wire [DATA_WIDTH-1:0] in0_data,
    input wire in1_valid,
    output wire in1_ready,
    input wire [DATA_WIDTH-1:0] in1_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
    reg out_valid_reg;
    reg [DATA_WIDTH-1:0] out_data_reg;
    wire can_output = in0_valid && in1_valid && !out_valid_reg;

    assign in0_ready = in1_valid && !out_valid_reg;
    assign in1_ready = in0_valid && !out_valid_reg;
    assign out_valid = out_valid_reg;
    assign out_data = out_data_reg;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        out_valid_reg <= 1'b0;
      end else begin
        if (can_output) begin
          out_valid_reg <= 1'b1;
          out_data_reg <= in0_data + in1_data;
        end else if (out_valid_reg && out_ready) begin
          out_valid_reg <= 1'b0;
        end
      end
    end
endmodule

module stream_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
    reg [DATA_WIDTH-1:0] data_reg;
    reg valid_reg;

    assign out_data = data_reg;
    assign out_valid = valid_reg;
    assign in_ready = !valid_reg || out_ready;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        valid_reg <= 1'b0;
      end else begin
        if (in_valid && in_ready) begin
          data_reg <= in_data;
          valid_reg <= 1'b1;
        end else if (out_ready && valid_reg) begin
          valid_reg <= 1'b0;
        end
      end
    end
endmodule

