module accumulator_core #(parameter SAMPLE_WIDTH = 8, parameter SUM_WIDTH = 8) (
    input wire [None-1:0] clk,
    input wire [None-1:0] rst_n,
    input wire [None-1:0] sample_valid,
    input wire [SAMPLE_WIDTH-1:0] sample,
    output wire [None-1:0] sample_ready,
    output wire [SUM_WIDTH-1:0] sum
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    localparam IDLE   = 1'b0;
    localparam ADDING = 1'b1;
    reg [SUM_WIDTH-1:0] sum_reg;
    reg                  state;

    assign sum = sum_reg;
    assign sample_ready = 1'b1;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        sum_reg <= {SUM_WIDTH{1'b0}};
        state   <= IDLE;
      end else begin
        if (sample_valid && sample_ready) begin
          sum_reg <= sum_reg + sample;
          state   <= ADDING;
        end else begin
          state <= IDLE;
        end
      end
    end
endmodule

module skid_buffer #(parameter DATA_WIDTH = 8) (
    input wire [None-1:0] clk,
    input wire [None-1:0] rst_n,
    input wire [None-1:0] in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire [None-1:0] in_ready,
    output wire [None-1:0] out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire [None-1:0] out_ready
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    localparam IDLE  = 2'd0;
    localparam STORE = 2'd1;
    localparam PASS  = 2'd2;
    reg [DATA_WIDTH-1:0] sample_reg;
    reg                  sample_valid;
    reg [DATA_WIDTH-1:0] skid_reg;
    reg                  skid_valid;
    reg [1:0]            state;

    assign out_data = sample_valid ? sample_reg : {DATA_WIDTH{1'b0}};
    assign out_valid = sample_valid;
    assign in_ready = !skid_valid;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        sample_reg   <= {DATA_WIDTH{1'b0}};
        sample_valid <= 1'b0;
        skid_reg     <= {DATA_WIDTH{1'b0}};
        skid_valid   <= 1'b0;
        state        <= IDLE;
      end else begin
        if (out_ready && sample_valid) begin
          sample_valid <= 1'b0;
        end
        if (in_valid && in_ready) begin
          if (!sample_valid) begin
            sample_reg   <= in_data;
            sample_valid <= 1'b1;
          end else begin
            skid_reg   <= in_data;
            skid_valid <= 1'b1;
          end
        end
        if (!sample_valid && skid_valid) begin
          sample_reg   <= skid_reg;
          sample_valid <= 1'b1;
          skid_valid   <= 1'b0;
        end
        if (sample_valid && skid_valid) begin
          state <= STORE;
        end else if (sample_valid && !skid_valid) begin
          state <= PASS;
        end else begin
          state <= IDLE;
        end
      end
    end
endmodule

module stream_join #(parameter DATA_WIDTH = 8) (
    input wire [None-1:0] clk,
    input wire [None-1:0] rst_n,
    input wire [None-1:0] in0_valid,
    input wire [DATA_WIDTH-1:0] in0_data,
    output wire [None-1:0] in0_ready,
    input wire [None-1:0] in1_valid,
    input wire [DATA_WIDTH-1:0] in1_data,
    output wire [None-1:0] in1_ready,
    output wire [None-1:0] out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire [None-1:0] out_ready
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    localparam WAIT_BOTH = 1'b0;
    wire _unused = WAIT_BOTH;

    assign out_valid = in0_valid && in1_valid;
    assign out_data  = in0_data;
    assign in0_ready = out_ready && in1_valid;
    assign in1_ready = out_ready && in0_valid;
endmodule

module stream_stage #(parameter DATA_WIDTH = 8) (
    input wire [None-1:0] clk,
    input wire [None-1:0] rst_n,
    input wire [None-1:0] in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire [None-1:0] in_ready,
    output wire [None-1:0] out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire [None-1:0] out_ready
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    localparam IDLE   = 1'b0;
    localparam OUTPUT = 1'b1;
    reg [DATA_WIDTH-1:0] data_reg;
    reg                  valid_reg;
    reg                  state;

    assign in_ready  = !valid_reg || out_ready;
    assign out_valid = valid_reg;
    assign out_data  = data_reg;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        data_reg  <= {DATA_WIDTH{1'b0}};
        valid_reg <= 1'b0;
        state     <= IDLE;
      end else begin
        if (out_ready && valid_reg) begin
          valid_reg <= 1'b0;
        end
        if (in_valid && in_ready) begin
          data_reg  <= in_data;
          valid_reg <= 1'b1;
        end
        state <= valid_reg ? OUTPUT : IDLE;
      end
    end
endmodule

