module accumulator_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    output wire sample_ready,
    input wire [DATA_WIDTH-1:0] sample,
    output wire sum_valid,
    input wire sum_ready,
    output wire [DATA_WIDTH-1:0] sum
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    reg [DATA_WIDTH-1:0] sum_reg;
    reg sum_valid_reg;

    assign sample_ready = !sum_valid_reg || sum_ready;
    assign sum_valid = sum_valid_reg;
    assign sum = sum_reg;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        sum_reg <= {DATA_WIDTH{1'b0}};
        sum_valid_reg <= 1'b0;
      end else begin
        if (sample_valid && sample_ready) begin
          sum_reg <= sum_reg + sample;
          sum_valid_reg <= 1'b1;
        end else if (sum_ready && sum_valid_reg) begin
          sum_valid_reg <= 1'b0;
        end
      end
    end
endmodule

module skid_buffer #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    reg  [DATA_WIDTH-1:0] main_data;
    reg  [DATA_WIDTH-1:0] skid_data;
    reg  main_valid;
    reg  skid_valid;

    assign out_data = main_data;
    assign out_valid = main_valid;
    assign in_ready = !skid_valid;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        main_valid <= 1'b0;
        skid_valid <= 1'b0;
        main_data <= {DATA_WIDTH{1'b0}};
        skid_data <= {DATA_WIDTH{1'b0}};
      end else begin
        if (out_ready && main_valid) begin
          if (skid_valid) begin
            main_data <= skid_data;
            skid_valid <= 1'b0;
          end else begin
            main_valid <= 1'b0;
          end
        end
        if (in_valid && in_ready) begin
          if (!main_valid) begin
            main_data <= in_data;
            main_valid <= 1'b1;
          end else begin
            skid_data <= in_data;
            skid_valid <= 1'b1;
          end
        end
      end
    end
endmodule

module stream_join #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in0_valid,
    output wire in0_ready,
    input wire [DATA_WIDTH-1:0] in0_data,
    input wire in1_valid,
    output wire in1_ready,
    input wire [DATA_WIDTH-1:0] in1_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    reg out_valid_reg;
    reg [DATA_WIDTH-1:0] out_data_reg;

    wire can_accept = !out_valid_reg || out_ready;
    assign in0_ready = can_accept && in1_valid;
    assign in1_ready = can_accept && in0_valid;
    assign out_valid = out_valid_reg;
    assign out_data = out_data_reg;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        out_valid_reg <= 1'b0;
        out_data_reg <= {DATA_WIDTH{1'b0}};
      end else begin
        if (in0_valid && in1_valid && in0_ready && in1_ready) begin
          out_valid_reg <= 1'b1;
          out_data_reg <= in0_data + in1_data;
        end else if (out_ready) begin
          out_valid_reg <= 1'b0;
        end
      end
    end
endmodule

module stream_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    reg out_valid_reg;
    reg [DATA_WIDTH-1:0] out_data_reg;

    assign in_ready = !out_valid_reg || out_ready;
    assign out_valid = out_valid_reg;
    assign out_data = out_data_reg;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        out_valid_reg <= 1'b0;
        out_data_reg <= {DATA_WIDTH{1'b0}};
      end else begin
        if (in_valid && in_ready) begin
          out_valid_reg <= 1'b1;
          out_data_reg <= in_data;
        end else if (out_ready) begin
          out_valid_reg <= 1'b0;
        end
      end
    end
endmodule

