module alu_core #(
    parameter WIDTH = 8
) (
    input wire [2:0] op,
    input wire [WIDTH-1:0] lhs,
    input wire [WIDTH-1:0] rhs,
    output reg [WIDTH-1:0] result,
    output reg carry
);

  wire [WIDTH:0] add_ext;
  wire [WIDTH:0] sub_ext;

  assign add_ext = {1'b0, lhs} + {1'b0, rhs};
  assign sub_ext = {1'b0, lhs} - {1'b0, rhs};

  always @* begin
    result = {WIDTH{1'b0}};
    carry = 1'b0;
    case (op)
      3'b000: begin
        result = add_ext[WIDTH-1:0];
        carry = add_ext[WIDTH];
      end
      3'b001: begin
        result = sub_ext[WIDTH-1:0];
        carry = sub_ext[WIDTH];
      end
      3'b010: result = lhs & rhs;
      3'b011: result = lhs | rhs;
      3'b100: result = lhs ^ rhs;
      3'b101: result = lhs << rhs[2:0];
      3'b110: result = lhs >> rhs[2:0];
      default: result = lhs;
    endcase
  end

endmodule

module control_decode (
    input wire [2:0] op,
    output wire [2:0] decoded_op
);

  assign decoded_op = op;

endmodule

module status_flags #(
    parameter WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire valid,
    input wire [WIDTH-1:0] alu_result,
    input wire alu_carry,
    output reg result_valid,
    output reg [WIDTH-1:0] result,
    output reg zero,
    output reg carry,
    output reg negative
);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      result_valid <= 1'b0;
      result <= {WIDTH{1'b0}};
      zero <= 1'b0;
      carry <= 1'b0;
      negative <= 1'b0;
    end else if (valid) begin
      result_valid <= 1'b1;
      result <= alu_result;
      zero <= (alu_result == {WIDTH{1'b0}});
      carry <= alu_carry;
      negative <= alu_result[WIDTH-1];
    end else begin
      result_valid <= 1'b0;
    end
  end

endmodule

module top (
    input wire clk,
    input wire rst_n,
    input wire valid,
    output wire ready,
    input wire [2:0] op,
    input wire [7:0] lhs,
    input wire [7:0] rhs,
    output wire result_valid,
    output wire [7:0] result,
    output wire zero,
    output wire carry,
    output wire negative
);

  wire [2:0] decoded_op;
  wire [7:0] alu_result;
  wire alu_carry;

  assign ready = 1'b1;

  control_decode u_control_decode (
    .op(op),
    .decoded_op(decoded_op)
  );

  alu_core #(
    .WIDTH(8)
  ) u_alu_core (
    .op(decoded_op),
    .lhs(lhs),
    .rhs(rhs),
    .result(alu_result),
    .carry(alu_carry)
  );

  status_flags #(
    .WIDTH(8)
  ) u_status_flags (
    .clk(clk),
    .rst_n(rst_n),
    .valid(valid),
    .alu_result(alu_result),
    .alu_carry(alu_carry),
    .result_valid(result_valid),
    .result(result),
    .zero(zero),
    .carry(carry),
    .negative(negative)
  );

endmodule

