    output reg [DATA_WIDTH-1:0] next_value_b_out,
    output reg done_b_out
);

  reg valid_reg;

  assign in_ready = !valid_reg || consume_ready;
  assign out_valid = valid_reg;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      valid_reg <= 1'b0;
      obs0_a_out <= {DATA_WIDTH{1'b0}};
