module counter_core #(
    parameter WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire en,
    output reg [WIDTH-1:0] count
);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      count <= {WIDTH{1'b0}};
    end else if (en) begin
      count <= count + {{(WIDTH-1){1'b0}}, 1'b1};
    end
  end

endmodule

module event_gate (
    input wire event_valid,
    output wire count_en
);

  assign count_en = event_valid;

endmodule

module top (
    input wire clk,
    input wire rst_n,
    input wire event_valid,
    output wire [7:0] count
);

  wire count_en;

  event_gate u_event_gate (
    .event_valid(event_valid),
    .count_en(count_en)
  );

  counter_core #(
    .WIDTH(8)
  ) u_counter_core (
    .clk(clk),
    .rst_n(rst_n),
    .en(count_en),
    .count(count)
  );

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg event_valid;
  wire [7:0] count;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .event_valid(event_valid),
    .count(count)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task pulse_event;
    begin
      @(negedge clk);
      event_valid = 1'b1;
      @(negedge clk);
      event_valid = 1'b0;
    end
  endtask

  initial begin
    rst_n = 1'b0;
    event_valid = 1'b0;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    pulse_event();
    pulse_event();
    repeat (2) @(posedge clk);
    #1;
    if (count !== 8'd2) begin
      $display("TEST_FAIL expected count=2 got %0d", count);
      $finish;
    end
    $display("TEST_PASS");
    $finish;
  end
endmodule

