module accumulator_core #(
    parameter WIDTH = 8,
    parameter SUM_WIDTH = 12
) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    output wire sample_ready,
    input wire [WIDTH-1:0] sample,
    output reg [SUM_WIDTH-1:0] sum
);

  assign sample_ready = 1'b1;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      sum <= {SUM_WIDTH{1'b0}};
    end else if (sample_valid) begin
      sum <= sum + {{(SUM_WIDTH-WIDTH){1'b0}}, sample};
    end
  end

endmodule

module skid_buffer #(
    parameter WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [WIDTH-1:0] out_data
);

  reg valid_r;
  reg [WIDTH-1:0] data_r;

  assign in_ready = !valid_r || out_ready;
  assign out_valid = valid_r;
  assign out_data = data_r;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      valid_r <= 1'b0;
      data_r <= {WIDTH{1'b0}};
    end else if (in_ready) begin
      valid_r <= in_valid;
      if (in_valid) begin
        data_r <= in_data;
      end
    end
  end

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg in_valid;
  wire in_ready;
  reg [7:0] in_data;
  wire sample_valid;
  wire [11:0] sum;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(in_valid),
    .in_ready(in_ready),
    .in_data(in_data),
    .sample_valid(sample_valid),
    .sum(sum)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task send_sample;
    input [7:0] value;
    begin
      @(negedge clk);
      in_valid = 1'b1;
      in_data = value;
      @(negedge clk);
      in_valid = 1'b0;
      in_data = 8'd0;
    end
  endtask

  initial begin
    rst_n = 1'b0;
    in_valid = 1'b0;
    in_data = 8'd0;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    send_sample(8'd3);
    send_sample(8'd4);
    repeat (2) @(posedge clk);
    #1;

    if (sum !== 12'd7) begin
      $display("TEST_FAIL expected sum=7 got %0d", sum);
      $finish;
    end
    if (in_ready !== 1'b1) begin
      $display("TEST_FAIL in_ready not asserted");
      $finish;
    end
    $display("TEST_PASS");
    $finish;
  end
endmodule

