module replay_store #(
    parameter DATA_WIDTH = 8,
    parameter DEPTH = 4
) (
    input wire clk,
    input wire rst_n,
    input wire write_valid,
    output wire write_ready,
    input wire [DATA_WIDTH-1:0] write_state,
    input wire write_action,
