module axi_lite_read_ctrl (
    input wire clk,
    input wire rst_n,
    input wire arvalid,
    output wire arready,
    input wire [3:0] araddr,
    output reg rvalid,
    input wire rready,
    output wire read_valid,
    output wire [3:0] read_addr
);

  wire accept_read;

  assign arready = !rvalid;
  assign accept_read = arvalid && arready;
  assign read_valid = accept_read;
  assign read_addr = araddr;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rvalid <= 1'b0;
    end else begin
      if (accept_read) begin
        rvalid <= 1'b1;
      end else if (rvalid && rready) begin
        rvalid <= 1'b0;
      end
    end
  end

endmodule

module axi_lite_write_ctrl #(
    parameter DATA_WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire awvalid,
    output wire awready,
    input wire [3:0] awaddr,
    input wire wvalid,
    output wire wready,
    input wire [DATA_WIDTH-1:0] wdata,
    input wire wstrb,
    output reg bvalid,
    input wire bready,
    output wire write_valid,
    output wire [3:0] write_addr,
    output wire [DATA_WIDTH-1:0] write_data
);

  wire accept_write;

  assign awready = !bvalid;
  assign wready = !bvalid;
  assign accept_write = awvalid && wvalid && awready && wready && wstrb;
  assign write_valid = accept_write;
  assign write_addr = awaddr;
  assign write_data = wdata;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      bvalid <= 1'b0;
    end else begin
      if (accept_write) begin
        bvalid <= 1'b1;
      end else if (bvalid && bready) begin
        bvalid <= 1'b0;
      end
    end
  end

endmodule

module control_reg_bank #(
    parameter DATA_WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire write_valid,
    input wire [3:0] write_addr,
    input wire [DATA_WIDTH-1:0] write_data,
    input wire read_valid,
    input wire [3:0] read_addr,
    output reg [DATA_WIDTH-1:0] read_data,
    input wire stream_done,
    output reg start_pulse,
    output reg [DATA_WIDTH-1:0] sample0,
    output reg [DATA_WIDTH-1:0] sample1,
    output reg irq_state
);

  reg [DATA_WIDTH-1:0] ctrl;
  reg busy;
  reg done;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      ctrl <= {DATA_WIDTH{1'b0}};
      sample0 <= {DATA_WIDTH{1'b0}};
      sample1 <= {DATA_WIDTH{1'b0}};
      busy <= 1'b0;
      done <= 1'b0;
      irq_state <= 1'b0;
      start_pulse <= 1'b0;
      read_data <= {DATA_WIDTH{1'b0}};
    end else begin
      start_pulse <= 1'b0;
      if (write_valid) begin
        case (write_addr)
          4'h0: begin
            ctrl <= write_data;
            if (write_data[0]) begin
              start_pulse <= 1'b1;
              busy <= 1'b1;
              done <= 1'b0;
            end
            if (write_data[1]) begin
              irq_state <= 1'b0;
            end
          end
          4'h4: sample0 <= write_data;
          4'h8: sample1 <= write_data;
          default: ctrl <= ctrl;
        endcase
      end
      if (stream_done) begin
        busy <= 1'b0;
        done <= 1'b1;
        irq_state <= 1'b1;
      end
      if (read_valid) begin
        case (read_addr)
          4'h0: read_data <= ctrl;
          4'h4: read_data <= sample0;
          4'h8: read_data <= sample1;
          4'hc: read_data <= {{(DATA_WIDTH-3){1'b0}}, irq_state, done, busy};
          default: read_data <= {DATA_WIDTH{1'b0}};
        endcase
      end
    end
  end

endmodule

module irq_status (
    input wire irq_in,
    output wire irq_out
);

  assign irq_out = irq_in;

endmodule

module sample_stream_adapter #(
    parameter DATA_WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_WIDTH-1:0] sample0,
    input wire [DATA_WIDTH-1:0] sample1,
    output reg tvalid,
    input wire tready,
    output reg [(2*DATA_WIDTH)-1:0] tdata,
    output reg tlast,
    output reg stream_done
);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      tvalid <= 1'b0;
      tdata <= {(2*DATA_WIDTH){1'b0}};
      tlast <= 1'b0;
      stream_done <= 1'b0;
    end else begin
      stream_done <= 1'b0;
      if (start && !tvalid) begin
        tvalid <= 1'b1;
        tdata <= {sample1, sample0};
        tlast <= 1'b1;
      end else if (tvalid && tready) begin
        tvalid <= 1'b0;
        tlast <= 1'b0;
        stream_done <= 1'b1;
      end
    end
  end

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg s_axi_awvalid;
  wire s_axi_awready;
  reg [3:0] s_axi_awaddr;
  reg s_axi_wvalid;
  wire s_axi_wready;
  reg [7:0] s_axi_wdata;
  reg s_axi_wstrb;
  wire s_axi_bvalid;
  reg s_axi_bready;
  reg s_axi_arvalid;
  wire s_axi_arready;
  reg [3:0] s_axi_araddr;
  wire s_axi_rvalid;
  reg s_axi_rready;
  wire [7:0] s_axi_rdata;
  wire m_axis_tvalid;
  reg m_axis_tready;
  wire [15:0] m_axis_tdata;
  wire m_axis_tlast;
  wire irq;
  integer wait_cycles;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .s_axi_awvalid(s_axi_awvalid),
    .s_axi_awready(s_axi_awready),
    .s_axi_awaddr(s_axi_awaddr),
    .s_axi_wvalid(s_axi_wvalid),
    .s_axi_wready(s_axi_wready),
    .s_axi_wdata(s_axi_wdata),
    .s_axi_wstrb(s_axi_wstrb),
    .s_axi_bvalid(s_axi_bvalid),
    .s_axi_bready(s_axi_bready),
    .s_axi_arvalid(s_axi_arvalid),
    .s_axi_arready(s_axi_arready),
    .s_axi_araddr(s_axi_araddr),
    .s_axi_rvalid(s_axi_rvalid),
    .s_axi_rready(s_axi_rready),
    .s_axi_rdata(s_axi_rdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tlast(m_axis_tlast),
    .irq(irq)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task axi_write;
    input [3:0] addr_i;
    input [7:0] data_i;
    begin
      @(negedge clk);
      s_axi_awvalid = 1'b1;
      s_axi_awaddr = addr_i;
      s_axi_wvalid = 1'b1;
      s_axi_wdata = data_i;
      s_axi_wstrb = 1'b1;
      s_axi_bready = 1'b1;
      while (!s_axi_awready || !s_axi_wready) begin
        @(negedge clk);
      end
      @(negedge clk);
      s_axi_awvalid = 1'b0;
      s_axi_wvalid = 1'b0;
      while (!s_axi_bvalid) begin
        @(negedge clk);
      end
      @(negedge clk);
      s_axi_bready = 1'b0;
    end
  endtask

  task axi_read_expect;
    input [3:0] addr_i;
    input [7:0] mask_i;
    input [7:0] expected_i;
    begin
      @(negedge clk);
      s_axi_arvalid = 1'b1;
      s_axi_araddr = addr_i;
      s_axi_rready = 1'b1;
      while (!s_axi_arready) begin
        @(negedge clk);
      end
      @(negedge clk);
      s_axi_arvalid = 1'b0;
      wait_cycles = 0;
      while (!s_axi_rvalid && wait_cycles < 16) begin
        @(posedge clk);
        #1;
        wait_cycles = wait_cycles + 1;
      end
      if (!s_axi_rvalid) begin
        $display("TEST_FAIL read response did not become valid");
        $finish;
      end
      if ((s_axi_rdata & mask_i) !== expected_i) begin
        $display("TEST_FAIL expected read masked %0h got %0h", expected_i, s_axi_rdata & mask_i);
        $finish;
      end
      @(negedge clk);
      s_axi_rready = 1'b0;
    end
  endtask

  initial begin
    rst_n = 1'b0;
    s_axi_awvalid = 1'b0;
    s_axi_awaddr = 4'h0;
    s_axi_wvalid = 1'b0;
    s_axi_wdata = 8'h00;
    s_axi_wstrb = 1'b0;
    s_axi_bready = 1'b0;
    s_axi_arvalid = 1'b0;
    s_axi_araddr = 4'h0;
    s_axi_rready = 1'b0;
    m_axis_tready = 1'b1;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    axi_write(4'h4, 8'h12);
    axi_write(4'h8, 8'h34);
    axi_write(4'h0, 8'h01);

    wait_cycles = 0;
    while (!m_axis_tvalid && wait_cycles < 16) begin
      @(posedge clk);
      #1;
      wait_cycles = wait_cycles + 1;
    end
    if (!m_axis_tvalid || m_axis_tdata !== 16'h3412 || m_axis_tlast !== 1'b1) begin
      $display("TEST_FAIL expected stream payload 0x3412 got valid=%0d data=%0h last=%0d",
               m_axis_tvalid, m_axis_tdata, m_axis_tlast);
      $finish;
    end
    repeat (2) @(posedge clk);
    #1;
    if (irq !== 1'b1) begin
      $display("TEST_FAIL expected irq set");
      $finish;
    end

    axi_read_expect(4'hc, 8'h06, 8'h06);
    axi_write(4'h0, 8'h02);
    axi_read_expect(4'hc, 8'h04, 8'h00);

    $display("TEST_PASS");
    $finish;
  end
endmodule

