module crc8_update (
    input wire [7:0] crc_in,
    input wire [7:0] data_in,
    output reg [7:0] crc_out
);

  integer bit_index;
  reg [7:0] crc_work;

  always @* begin
    crc_work = crc_in ^ data_in;
    for (bit_index = 0; bit_index < 8; bit_index = bit_index + 1) begin
      if (crc_work[7]) begin
        crc_work = (crc_work << 1) ^ 8'h07;
      end else begin
        crc_work = crc_work << 1;
      end
    end
    crc_out = crc_work;
  end

endmodule

module crc_status (
    input wire clk,
    input wire rst_n,
    input wire frame_done,
    input wire out_ready,
    input wire [7:0] frame_crc,
    input wire [7:0] expected_crc,
    output reg out_valid,
    output reg [7:0] crc_value,
    output reg crc_match
);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      out_valid <= 1'b0;
      crc_value <= 8'h00;
      crc_match <= 1'b0;
    end else if (frame_done) begin
      out_valid <= 1'b1;
      crc_value <= frame_crc;
      crc_match <= (frame_crc == expected_crc);
    end else if (out_valid && out_ready) begin
      out_valid <= 1'b0;
    end
  end

endmodule

module stream_frame_accumulator (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire frame_end,
    input wire out_ready,
    input wire [7:0] crc_next,
    output reg [7:0] crc_state,
    output reg frame_done,
    output reg [7:0] frame_crc
);

  wire accept;

  assign in_ready = !frame_done || out_ready;
  assign accept = in_valid && in_ready;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      crc_state <= 8'h00;
      frame_done <= 1'b0;
      frame_crc <= 8'h00;
    end else begin
      if (frame_done && out_ready) begin
        frame_done <= 1'b0;
      end
      if (accept) begin
        crc_state <= crc_next;
        if (frame_end) begin
          frame_done <= 1'b1;
          frame_crc <= crc_next;
        end
      end
    end
  end

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg in_valid;
  wire in_ready;
  reg [7:0] in_data;
  reg frame_start;
  reg frame_end;
  reg [7:0] expected_crc;
  wire out_valid;
  reg out_ready;
  wire [7:0] crc_value;
  wire crc_match;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(in_valid),
    .in_ready(in_ready),
    .in_data(in_data),
    .frame_start(frame_start),
    .frame_end(frame_end),
    .expected_crc(expected_crc),
    .out_valid(out_valid),
    .out_ready(out_ready),
    .crc_value(crc_value),
    .crc_match(crc_match)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task send_byte;
    input [7:0] value;
    input start_i;
    input end_i;
    begin
      @(negedge clk);
      in_valid = 1'b1;
      in_data = value;
      frame_start = start_i;
      frame_end = end_i;
      @(negedge clk);
      if (in_ready !== 1'b1) begin
        $display("TEST_FAIL input was not ready");
        $finish;
      end
      in_valid = 1'b0;
      in_data = 8'd0;
      frame_start = 1'b0;
      frame_end = 1'b0;
    end
  endtask

  initial begin
    rst_n = 1'b0;
    in_valid = 1'b0;
    in_data = 8'd0;
    frame_start = 1'b0;
    frame_end = 1'b0;
    expected_crc = 8'h7c;
    out_ready = 1'b1;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    send_byte(8'h12, 1'b1, 1'b0);
    send_byte(8'h34, 1'b0, 1'b0);
    send_byte(8'h56, 1'b0, 1'b1);

    @(posedge clk);
    #1;
    if (out_valid !== 1'b1) begin
      $display("TEST_FAIL out_valid was not asserted");
      $finish;
    end
    if (crc_value !== 8'h7c) begin
      $display("TEST_FAIL expected crc=7c got %0h", crc_value);
      $finish;
    end
    if (crc_match !== 1'b1) begin
      $display("TEST_FAIL crc_match was not asserted");
      $finish;
    end
    @(posedge clk);
    #1;
    if (out_valid !== 1'b0) begin
      $display("TEST_FAIL out_valid did not clear after ready");
      $finish;
    end
    $display("TEST_PASS");
    $finish;
  end
endmodule

