module skid_buffer #(
    parameter WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [WIDTH-1:0] out_data
);

  reg valid_r;
  reg [WIDTH-1:0] data_r;

  assign in_ready = !valid_r || out_ready;
  assign out_valid = valid_r;
  assign out_data = data_r;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      valid_r <= 1'b0;
      data_r <= {WIDTH{1'b0}};
    end else if (in_ready) begin
      valid_r <= in_valid;
      if (in_valid) begin
        data_r <= in_data;
      end
    end
  end

endmodule

module stream_stage #(
    parameter WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [WIDTH-1:0] in_data,
    output reg out_valid,
    input wire out_ready,
    output reg [WIDTH-1:0] out_data
);

  assign in_ready = !out_valid || out_ready;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      out_valid <= 1'b0;
      out_data <= {WIDTH{1'b0}};
    end else if (in_ready) begin
      out_valid <= in_valid;
      if (in_valid) begin
        out_data <= in_data;
      end
    end
  end

endmodule

module vector_mac_core #(
    parameter DATA_WIDTH = 8,
    parameter SCORE_WIDTH = 16
) (
    input wire clk,
    input wire rst_n,
    input wire feature_valid,
    output wire feature_ready,
    input wire [DATA_WIDTH-1:0] feature_data,
    input wire weight_valid,
    output wire weight_ready,
    input wire [DATA_WIDTH-1:0] weight_data,
    input wire [SCORE_WIDTH-1:0] bias,
    output reg score_valid,
    input wire score_ready,
    output reg [SCORE_WIDTH-1:0] score_data
);

  reg [SCORE_WIDTH-1:0] accumulator;
  reg [1:0] vector_index;
  localparam [1:0] LAST_INDEX = 2'd3;
  wire accept_pair;
  wire [SCORE_WIDTH-1:0] product;
  wire [SCORE_WIDTH-1:0] next_accumulator;

  assign feature_ready = weight_valid && !score_valid;
  assign weight_ready = feature_valid && !score_valid;
  assign accept_pair = feature_valid && feature_ready && weight_valid && weight_ready;
  assign product = feature_data * weight_data;
  assign next_accumulator = accumulator + product;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      accumulator <= {SCORE_WIDTH{1'b0}};
      vector_index <= 2'd0;
      score_valid <= 1'b0;
      score_data <= {SCORE_WIDTH{1'b0}};
    end else begin
      if (score_valid && score_ready) begin
        score_valid <= 1'b0;
      end
      if (accept_pair) begin
        if (vector_index == LAST_INDEX) begin
          score_data <= next_accumulator + bias;
          score_valid <= 1'b1;
          accumulator <= {SCORE_WIDTH{1'b0}};
          vector_index <= 2'd0;
        end else begin
          accumulator <= next_accumulator;
          vector_index <= vector_index + 2'd1;
        end
      end
    end
  end

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg feature_valid;
  wire feature_ready;
  reg [7:0] feature_data;
  reg weight_valid;
  wire weight_ready;
  reg [7:0] weight_data;
  reg [15:0] bias;
  wire score_valid;
  reg score_ready;
  wire [15:0] score_data;
  integer wait_cycles;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .feature_valid(feature_valid),
    .feature_ready(feature_ready),
    .feature_data(feature_data),
    .weight_valid(weight_valid),
    .weight_ready(weight_ready),
    .weight_data(weight_data),
    .bias(bias),
    .score_valid(score_valid),
    .score_ready(score_ready),
    .score_data(score_data)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task send_pair;
    input [7:0] feature;
    input [7:0] weight;
    begin
      @(negedge clk);
      feature_valid = 1'b1;
      weight_valid = 1'b1;
      feature_data = feature;
      weight_data = weight;
      while (!(feature_ready && weight_ready)) begin
        @(negedge clk);
      end
      @(negedge clk);
      feature_valid = 1'b0;
      weight_valid = 1'b0;
      feature_data = 8'd0;
      weight_data = 8'd0;
    end
  endtask

  task expect_score;
    input [15:0] expected;
    begin
      wait_cycles = 0;
      while (score_valid !== 1'b1 && wait_cycles < 16) begin
        @(posedge clk);
        #1;
        wait_cycles = wait_cycles + 1;
      end
      if (score_valid !== 1'b1) begin
        $display("TEST_FAIL score did not become valid");
        $finish;
      end
      if (score_data !== expected) begin
        $display("TEST_FAIL expected score=%0d got %0d", expected, score_data);
        $finish;
      end
      @(negedge clk);
    end
  endtask

  initial begin
    rst_n = 1'b0;
    feature_valid = 1'b0;
    feature_data = 8'd0;
    weight_valid = 1'b0;
    weight_data = 8'd0;
    bias = 16'd0;
    score_ready = 1'b1;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    bias = 16'd3;
    send_pair(8'd1, 8'd2);
    send_pair(8'd2, 8'd3);
    send_pair(8'd3, 8'd4);
    send_pair(8'd4, 8'd5);
    expect_score(16'd43);

    bias = 16'd1;
    send_pair(8'd2, 8'd1);
    send_pair(8'd1, 8'd2);
    send_pair(8'd0, 8'd3);
    send_pair(8'd3, 8'd4);
    expect_score(16'd17);

    $display("TEST_PASS");
    $finish;
  end
endmodule

