module discount_core #(parameter DATA_WIDTH = 8, parameter SCALE_SHIFT = 4) (
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] reward,
    input wire [DATA_WIDTH-1:0] next_value,
    input wire [DATA_WIDTH-1:0] gamma,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] discounted_return
);
    // Combinational ready/valid passthrough
    assign in_ready  = out_ready;
    assign out_valid = in_valid & out_ready;

    // Treat all operands as signed fixed-point.
    // gamma is Q4.4, reward and next_value are Q8.0.
    // Compute discounted_return = reward + (gamma * next_value) >>> SCALE_SHIFT
    wire signed [DATA_WIDTH-1:0] r   = $signed(reward);
    wire signed [DATA_WIDTH-1:0] nv  = $signed(next_value);
    wire signed [DATA_WIDTH-1:0] g   = $signed(gamma);

    // Multiply with enough width to avoid overflow
    wire signed [2*DATA_WIDTH-1:0] product = g * nv;
    wire signed [2*DATA_WIDTH-1:0] shifted = product >>> SCALE_SHIFT;
    wire signed [2*DATA_WIDTH-1:0] sum     = r + shifted;

    // Truncate/saturate to DATA_WIDTH bits (no explicit saturation)
    assign discounted_return = sum[DATA_WIDTH-1:0];
endmodule

module stream_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] td_error,
    input wire [DATA_WIDTH-1:0] updated_value,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] td_error_out,
    output wire [DATA_WIDTH-1:0] updated_value_out
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    // Internal state
    reg                  valid_r;
    reg [DATA_WIDTH-1:0] td_error_r;
    reg [DATA_WIDTH-1:0] updated_value_r;

    // Ready to accept new data when output buffer empty or downstream accepts current data
    assign in_ready = !valid_r || out_ready;

    // Outputs
    assign out_valid         = valid_r;
    assign td_error_out      = td_error_r;
    assign updated_value_out = updated_value_r;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        valid_r <= 1'b0;
      end else begin
        if (in_valid && in_ready) begin
          // capture new transaction
          td_error_r      <= td_error;
          updated_value_r <= updated_value;
          valid_r         <= 1'b1;
        end else if (valid_r && out_ready) begin
          // handshake complete, mark not valid
          valid_r <= 1'b0;
        end
      end
    end
endmodule

module td_input_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] reward,
    input wire [DATA_WIDTH-1:0] value,
    input wire [DATA_WIDTH-1:0] next_value,
    input wire [DATA_WIDTH-1:0] gamma,
    input wire [DATA_WIDTH-1:0] alpha,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] reward_out,
    output wire [DATA_WIDTH-1:0] value_out,
    output wire [DATA_WIDTH-1:0] next_value_out,
    output wire [DATA_WIDTH-1:0] gamma_out,
    output wire [DATA_WIDTH-1:0] alpha_out
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    // Internal state
    reg                  valid_r;
    reg [DATA_WIDTH-1:0] reward_r;
    reg [DATA_WIDTH-1:0] value_r;
    reg [DATA_WIDTH-1:0] next_value_r;
    reg [DATA_WIDTH-1:0] gamma_r;
    reg [DATA_WIDTH-1:0] alpha_r;

    // Ready to accept new data when output buffer empty or downstream accepts current data
    assign in_ready = !valid_r || out_ready;

    // Outputs
    assign out_valid = valid_r;
    assign reward_out     = reward_r;
    assign value_out      = value_r;
    assign next_value_out = next_value_r;
    assign gamma_out      = gamma_r;
    assign alpha_out      = alpha_r;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        valid_r <= 1'b0;
        // data registers need not be reset
      end else begin
        if (in_valid && in_ready) begin
          // capture new transaction
          reward_r     <= reward;
          value_r      <= value;
          next_value_r <= next_value;
          gamma_r      <= gamma;
          alpha_r      <= alpha;
          valid_r      <= 1'b1;
        end else if (valid_r && out_ready) begin
          // handshake complete, mark not valid
          valid_r <= 1'b0;
        end
      end
    end
endmodule

module td_update_core #(parameter DATA_WIDTH = 8, parameter SCALE_SHIFT = 4) (
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] discounted_return,
    input wire [DATA_WIDTH-1:0] value,
    input wire [DATA_WIDTH-1:0] alpha,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] td_error,
    output wire [DATA_WIDTH-1:0] updated_value
);
    // Combinational ready/valid passthrough
    assign in_ready  = out_ready;
    assign out_valid = in_valid & out_ready;

    // Treat operands as signed
    wire signed [DATA_WIDTH-1:0] dr    = $signed(discounted_return);
    wire signed [DATA_WIDTH-1:0] v     = $signed(value);
    wire signed [DATA_WIDTH-1:0] a     = $signed(alpha);

    // TD error: discounted_return - value
    wire signed [DATA_WIDTH:0] err_ext = dr - v; // one extra bit for possible overflow

    // updated_value = value + (alpha * td_error) >>> SCALE_SHIFT
    wire signed [2*DATA_WIDTH:0] mul    = a * err_ext;  // sufficient width
    wire signed [2*DATA_WIDTH:0] scaled = mul >>> SCALE_SHIFT;
    wire signed [DATA_WIDTH:0]   new_val = v + $signed(scaled[DATA_WIDTH-1:0]);

    // Outputs (truncate to DATA_WIDTH)
    assign td_error      = err_ext[DATA_WIDTH-1:0];
    assign updated_value = new_val[DATA_WIDTH-1:0];
endmodule

