module accumulator_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    input wire [DATA_WIDTH-1:0] sample,
    input wire sample_ready,
    output wire [DATA_WIDTH-1:0] sum
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    reg [DATA_WIDTH-1:0] accum_sum;

    assign sum = accum_sum;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        accum_sum <= {DATA_WIDTH{1'b0}};
      end else begin
        if (sample_valid && sample_ready) begin
          accum_sum <= accum_sum + sample;
        end
      end
    end
endmodule

module skid_buffer #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    input wire out_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    reg                  skid_valid;
    reg [DATA_WIDTH-1:0] skid_data;

    assign out_valid = in_valid || skid_valid;
    assign out_data  = skid_valid ? skid_data : in_data;
    assign in_ready  = !skid_valid || out_ready;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        skid_valid <= 1'b0;
        skid_data  <= {DATA_WIDTH{1'b0}};
      end else begin
        if (out_ready) begin
          if (in_valid && skid_valid) begin
            skid_data <= in_data;
            // skid_valid remains 1
          end else if (skid_valid) begin
            skid_valid <= 1'b0;
          end else if (in_valid) begin
            // pass through, nothing to store
          end
        end else begin // out_ready is low
          if (in_valid) begin
            skid_valid <= 1'b1;
            skid_data <= in_data;
          end
        end
      end
    end
endmodule

module stream_join #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in0_valid,
    input wire [DATA_WIDTH-1:0] in0_data,
    output wire in0_ready,
    input wire in1_valid,
    input wire [DATA_WIDTH-1:0] in1_data,
    output wire in1_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    assign out_valid = in0_valid && in1_valid;
    assign out_data  = in0_data + in1_data;
    assign in0_ready = in1_valid && out_ready;
    assign in1_ready = in0_valid && out_ready;
endmodule

module stream_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    reg                  out_valid_reg;
    reg [DATA_WIDTH-1:0] out_data_reg;

    assign out_valid = out_valid_reg;
    assign out_data  = out_data_reg;
    assign in_ready  = !out_valid_reg || out_ready;

    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        out_valid_reg <= 1'b0;
        out_data_reg  <= {DATA_WIDTH{1'b0}};
      end else begin
        if (in_valid && in_ready) begin
          out_data_reg  <= in_data;
          out_valid_reg <= 1'b1;
        end else if (out_ready && out_valid_reg) begin
          out_valid_reg <= 1'b0;
        end
      end
    end
endmodule

module top #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in0_valid,
    input wire [DATA_WIDTH-1:0] in0_data,
