module accumulator_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid_in,
    output wire sample_ready_out,
    input wire [DATA_WIDTH-1:0] sample,
    output wire [DATA_WIDTH-1:0] sum,
    output wire sample_valid_out
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    // Treat sample_ready_out as downstream ready input (not driven here)
    wire downstream_ready = sample_ready_out;
    reg [DATA_WIDTH-1:0] sum_r;
    reg valid_r;
    wire input_fire = sample_valid_in && (downstream_ready || !valid_r);

    assign sum = sum_r;

    always @(posedge clk) begin
      if (!rst_n) begin
        sum_r <= 0;
        valid_r <= 0;
      end else begin
        if (input_fire) begin
          sum_r <= sum_r + sample;
          valid_r <= 1'b1;
        end else if (valid_r && downstream_ready) begin
          valid_r <= 1'b0;
        end
      end
    end

    assign sample_valid_out = valid_r;
endmodule

module skid_buffer #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    // Standard skid buffer
    reg [DATA_WIDTH-1:0] data_reg;
    reg valid_reg;

    assign out_data = valid_reg ? data_reg : in_data;
    assign out_valid = valid_reg || in_valid;
    assign in_ready = !valid_reg || out_ready;

    always @(posedge clk) begin
      if (!rst_n) begin
        data_reg <= 0;
        valid_reg <= 0;
      end else begin
        if (in_valid && in_ready) begin
          data_reg <= in_data;
          valid_reg <= 1'b1;
        end else if (valid_reg && out_ready) begin
          valid_reg <= 1'b0;
        end
      end
    end
endmodule

module stream_join #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in0_valid,
    output wire in0_ready,
    input wire [DATA_WIDTH-1:0] in0_data,
    input wire in1_valid,
    output wire in1_ready,
    input wire [DATA_WIDTH-1:0] in1_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    // Combinational join: output valid when both are valid
    assign out_valid = in0_valid && in1_valid;
    assign in0_ready = out_ready && in1_valid;
    assign in1_ready = out_ready && in0_valid;
    assign out_data = in0_data + in1_data;
endmodule

module stream_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
    // Simple pipeline register stage
    reg [DATA_WIDTH-1:0] data_r;
    reg valid_r;

    assign out_data = data_r;
    assign out_valid = valid_r;
    assign in_ready = !valid_r || out_ready;

    always @(posedge clk) begin
      if (!rst_n) begin
        data_r <= 0;
        valid_r <= 0;
      end else begin
        if (in_valid && in_ready) begin
          data_r <= in_data;
          valid_r <= 1'b1;
        end else if (valid_r && out_ready) begin
          valid_r <= 1'b0;
        end
      end
    end
endmodule

