    write_cfg(3'd2, 8'd3);
    write_cfg(3'd3, 8'd0);
    write_cfg(3'd4, 8'd4);
    write_cfg(3'd5, 8'd1);

    send_sample(8'd4, 8'd2, 8'd1, 8'd8, 1'b0);
    expect_result(1'b0, 8'd7, 8'd7, 1'b0);

    send_sample(8'd1, 8'd5, 8'd2, 8'd15, 1'b1);
    expect_result(1'b1, 8'd9, 8'd11, 1'b1);

    if (irq !== 1'b1) begin
      $display("TEST_FAIL expected irq after done result");
      $finish;
    end

    $display("TEST_PASS");
    $finish;
  end
