        end
        result_valid <= 1'b0;
      end
      if (in_valid && out_ready) begin
        result_valid <= 1'b1;
        selected_action_a_out <= selected_action_a;
        value_estimate_a_out <= value_estimate_a;
        updated_value_a_out <= updated_value_a;
