);

  wire s0_valid;
  wire s0_ready;
  wire [7:0] s0_data;
  wire s1_valid;
  wire s1_ready;
  wire [7:0] s1_data;
  wire joined_valid;
  wire joined_ready;
  wire [7:0] joined_data;
  wire accum_valid;
  wire accum_ready;
