  );

  skid_buffer #(
    .WIDTH(8)
  ) u_skid1 (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(in1_valid),
    .in_ready(in1_ready),
    .in_data(in1_data),
    .out_valid(s1_valid),
    .out_ready(s1_ready),
    .out_data(s1_data)
  );

  stream_join #(
    .WIDTH(8)
  ) u_stream_join (
    .in0_valid(s0_valid),
    .in0_ready(s0_ready),
    .in0_data(s0_data),
    .in1_valid(s1_valid),
    .in1_ready(s1_ready),
    .in1_data(s1_data),
    .out_valid(joined_valid),
    .out_ready(joined_ready),
    .out_data(joined_data)
  );

  accumulator_core #(
    .WIDTH(8)
  ) u_accumulator_core (
    .clk(clk),
    .rst_n(rst_n),
    .sample_valid(joined_valid),
    .sample_ready(joined_ready),
    .sample(joined_data),
    .sum(accum_sum)
  );

  assign accum_valid = joined_valid && joined_ready;

  stream_stage #(
    .WIDTH(12)
  ) u_stage (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(accum_valid),
    .in_ready(accum_ready),
