////////////////////////////////////////////////////////////////////////////////
// counter_core.v
// 8-bit event counter. Increments on rising edge of event_pulse_in.
// Outputs count and a single-cycle count_valid pulse.
////////////////////////////////////////////////////////////////////////////////

`timescale 1ns / 1ps

module counter_core (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       event_pulse_in,
    output reg  [7:0] count,
    output reg        count_valid
);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count        <= 8'd0;
            count_valid  <= 1'b0;
        end else begin
            count_valid  <= event_pulse_in;
            if (event_pulse_in) begin
                count <= count + 1'b1;
            end
        end
    end

endmodule

////////////////////////////////////////////////////////////////////////////////
// event_gate.v
// Rising edge detector for event_in. Outputs a single-cycle pulse on
// event_pulse_out when a rising edge is detected.
////////////////////////////////////////////////////////////////////////////////

`timescale 1ns / 1ps

module event_gate (
    input  wire clk,
    input  wire rst_n,
    input  wire event_in,
    output reg  event_pulse_out
);

    reg event_in_delay;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            event_in_delay   <= 1'b0;
            event_pulse_out  <= 1'b0;
        end else begin
            event_in_delay   <= event_in;
            event_pulse_out  <= event_in & ~event_in_delay;  // rising edge
        end
    end

endmodule

////////////////////////////////////////////////////////////////////////////////
// top.v
// Integration wrapper for event counter project
////////////////////////////////////////////////////////////////////////////////

`timescale 1ns / 1ps

module top (
    input  wire clk,
    input  wire rst_n,
    input  wire event_in,
    output wire [7:0] count,
    output wire count_valid
);

    // Internal wire from event_gate to counter_core
    wire event_pulse;

    // Instantiate event_gate
    event_gate event_gate (
        .clk             (clk),
        .rst_n           (rst_n),
        .event_in        (event_in),
        .event_pulse_out (event_pulse)
    );

    // Instantiate counter_core
    counter_core counter (
        .clk             (clk),
        .rst_n           (rst_n),
        .event_pulse_in  (event_pulse),
        .count           (count),
        .count_valid     (count_valid)
    );

endmodule

////////////////////////////////////////////////////////////////////////////////
// tb_top.v
// Self-checking testbench for event counter.
// Applies a sequence of event pulses and verifies count and count_valid.
////////////////////////////////////////////////////////////////////////////////

`timescale 1ns / 1ps

module tb_top;

    reg  clk;
    reg  rst_n;
    reg  event_in;
    wire [7:0] count;
    wire count_valid;

    // Clock generation: 100 MHz -> period 10 ns
    always #5 clk = ~clk;

    // Instantiate DUT
    top dut (
        .clk         (clk),
        .rst_n       (rst_n),
        .event_in    (event_in),
        .count       (count),
        .count_valid (count_valid)
    );

    // Test sequence
    initial begin
        // Initialize
        clk = 0;
        rst_n = 0;
        event_in = 0;
        #20;
        rst_n = 1;
        #10;

        // Check initial state
        if (count !== 8'd0 || count_valid !== 1'b0) begin
            $display("TEST_FAIL: initial values");
            $finish;
        end

        // Apply 5 event pulses, each spaced 3 clock cycles apart
        repeat (5) begin
            @(posedge clk);
            event_in = 1;
            @(posedge clk);
            event_in = 0;
            // Wait for outputs to settle (should be ready at next posedge)
            @(posedge clk);
            // Check count_valid should be 1 for the pulse, then 0
            if (count_valid !== 1'b1) begin
                $display("TEST_FAIL: count_valid not asserted after event");
                $finish;
            end
            @(posedge clk);
            if (count_valid !== 1'b0) begin
                $display("TEST_FAIL: count_valid not deasserted");
                $finish;
            end
        end

        // After 5 pulses, count should be 5
        if (count !== 8'd5) begin
            $display("TEST_FAIL: count = %d, expected 5", count);
            $finish;
        end

        // Test overflow: apply 251 more pulses to reach 256 -> 0
        repeat (251) begin
            @(posedge clk);
            event_in = 1;
            @(posedge clk);
            event_in = 0;
            @(posedge clk);
            @(posedge clk);
        end

        // Now count should be 0 (256 total pulses, 8-bit wrap)
        if (count !== 8'd0) begin
            $display("TEST_FAIL: overflow test, count = %d, expected 0", count);
            $finish;
        end

        // Apply one more pulse to verify count becomes 1
        @(posedge clk);
        event_in = 1;
        @(posedge clk);
        event_in = 0;
        @(posedge clk);
        @(posedge clk);
        if (count !== 8'd1 || count_valid !== 1'b0) begin
            $display("TEST_FAIL: final pulse, count = %d, expected 1", count);
            $finish;
        end

        $display("TEST_PASS");
        $finish;
    end

endmodule

