module accumulator_core #(
   parameter DATA_WIDTH = 8
)(
   input  wire                     clk,
   input  wire                     rst_n,
   // Input stream
   input  wire                     in_valid,
   output reg                      in_ready,
   input  wire [DATA_WIDTH-1:0]    in_data,
   // Output stream
   output reg                      out_valid,
   input  wire                     out_ready,
   output reg [DATA_WIDTH-1:0]     out_data
);

   reg [DATA_WIDTH-1:0] acc_reg;

   // in_ready: accept if output is not valid or output ready
   assign in_ready = out_ready | ~out_valid;

   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         acc_reg <= 0;
         out_valid <= 0;
         out_data <= 0;
      end else begin
         if (in_valid & in_ready) begin
            acc_reg <= acc_reg + in_data;
            out_data <= acc_reg + in_data;
            out_valid <= 1;
         end else if (out_ready) begin
            out_valid <= 0;
         end
      end
   end

endmodule

module skid_buffer #(
   parameter DATA_WIDTH = 8
)(
   input  wire                     clk,
   input  wire                     rst_n,
   // input stream
   input  wire                     in_valid,
   output reg                      in_ready,
   input  wire [DATA_WIDTH-1:0]    in_data,
   // output stream
   output reg                      out_valid,
   input  wire                     out_ready,
   output reg [DATA_WIDTH-1:0]     out_data
);

   reg [DATA_WIDTH-1:0] skid_data;
   reg skid_valid;

   // in_ready is high when we can accept new data: either out_valid is low or out_ready is high or skid is free
   assign in_ready = ~(out_valid & ~out_ready & skid_valid);

   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         out_valid <= 0;
         skid_valid <= 0;
      end else begin
         if (in_valid & in_ready) begin
            if (out_valid & ~out_ready) begin
               // output busy, store in skid
               skid_data <= in_data;
               skid_valid <= 1;
            end else begin
               // output free, pass through
               out_data <= in_data;
               out_valid <= 1;
            end
         end
         if (out_ready) begin
            if (skid_valid) begin
               out_data <= skid_data;
               out_valid <= 1;
               skid_valid <= 0;
            end else begin
               out_valid <= 0;
            end
         end
      end
   end

endmodule

module stream_join #(
   parameter DATA_WIDTH = 8
)(
   input  wire                     clk,
   input  wire                     rst_n,
   // Input stream 0
   input  wire                     in0_valid,
   output reg                      in0_ready,
   input  wire [DATA_WIDTH-1:0]    in0_data,
   // Input stream 1
   input  wire                     in1_valid,
   output reg                      in1_ready,
   input  wire [DATA_WIDTH-1:0]    in1_data,
   // Output stream
   output reg                      out_valid,
   input  wire                     out_ready,
   output reg [DATA_WIDTH-1:0]     out_data
);

   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         out_valid <= 0;
      end else begin
         if (out_ready) begin
            if (in0_valid & in1_valid) begin
               out_valid <= 1;
               out_data <= in0_data + in1_data;
            end else begin
               out_valid <= 0;
            end
         end
         // else hold
      end
   end

   assign in0_ready = out_ready & in1_valid;
   assign in1_ready = out_ready & in0_valid;

endmodule

module stream_stage #(
   parameter DATA_WIDTH = 8
)(
   input  wire                     clk,
   input  wire                     rst_n,
   // Input stream
   input  wire                     in_valid,
   output reg                      in_ready,
   input  wire [DATA_WIDTH-1:0]    in_data,
   // Output stream
   output reg                      out_valid,
   input  wire                     out_ready,
   output reg [DATA_WIDTH-1:0]     out_data
);

   // in_ready: accept if we are not holding a valid output or downstream is ready
   assign in_ready = out_ready | ~out_valid;

   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         out_valid <= 0;
      end else begin
         if (in_ready) begin
            if (in_valid) begin
               out_valid <= 1;
               out_data <= in_data;
            end else begin
               out_valid <= 0;
            end
         end
      end
   end

endmodule

module tb_top;
   reg clk, rst_n;
   reg [7:0] in0_data, in1_data;
   reg in0_valid, in1_valid;
   wire in0_ready, in1_ready;
   wire [7:0] out_data;
   wire out_valid;
   reg out_ready;

   top #(.DATA_WIDTH(8)) dut (.*);

   always #5 clk = ~clk;

   reg [7:0] in0_seq [0:2] = {8'd1, 8'd2, 8'd3};
   reg [7:0] in1_seq [0:2] = {8'd4, 8'd5, 8'd6};
   reg [7:0] expected [0:2] = {8'd5, 8'd12, 8'd21};
   integer i;

   initial begin
      clk = 0;
      rst_n = 0;
      in0_valid = 0;
      in1_valid = 0;
      out_ready = 1;
      #20 rst_n = 1;
      #10;
      for (i=0; i<3; i=i+1) begin
         @(posedge clk);
         in0_valid = 1;
         in0_data = in0_seq[i];
         in1_valid = 1;
         in1_data = in1_seq[i];
         // wait for output
         while (!out_valid) @(posedge clk);
         if (out_data !== expected[i]) begin
            $display("TEST_FAIL: mismatch at %0d, expected %d, got %d", i, expected[i], out_data);
            $finish;
         end
         in0_valid = 0;
         in1_valid = 0;
      end
      #10;
      $display("TEST_PASS");
      $finish;
   end
endmodule

