// accumulator_core: accumulates input values, outputs running sum
// When valid_in and ready_in are high, adds data_in to accumulator and outputs result

module accumulator_core #(
    parameter DATA_WIDTH = 8
) (
    input  wire                    clk,
    input  wire                    rst_n,
    input  wire [DATA_WIDTH-1:0]   data_in,
    input  wire                    valid_in,
    output wire                    ready_out,
    output wire [DATA_WIDTH-1:0]   data_out,
    output wire                    valid_out,
    input  wire                    ready_in
);

    reg [DATA_WIDTH-1:0] acc_reg;
    reg                  acc_valid;

    wire fire = valid_in & ready_out;
    wire transfer_out = acc_valid & ready_in;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            acc_reg   <= {DATA_WIDTH{1'b0}};
            acc_valid <= 1'b0;
        end else if (fire) begin
            acc_reg   <= acc_reg + data_in;
            acc_valid <= 1'b1;
        end else if (transfer_out) begin
            acc_valid <= 1'b0;
        end
    end

    assign ready_out = ~acc_valid | transfer_out;
    assign data_out  = acc_reg;
    assign valid_out = acc_valid;

endmodule

// skid_buffer: single-level buffer with valid-ready handshake
// Asserts ready_out when not holding data, else after transfer

module skid_buffer #(
    parameter DATA_WIDTH = 8
) (
    input  wire                    clk,
    input  wire                    rst_n,
    input  wire [DATA_WIDTH-1:0]   data_in,
    input  wire                    valid_in,
    output wire                    ready_out,
    output wire [DATA_WIDTH-1:0]   data_out,
    output wire                    valid_out,
    input  wire                    ready_in
);

    reg [DATA_WIDTH-1:0] buf_data;
    reg                  buf_valid;

    wire load_to_buffer = valid_in & ready_out;
    wire transfer_out   = valid_out & ready_in;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            buf_valid <= 1'b0;
            buf_data  <= {DATA_WIDTH{1'b0}};
        end else if (load_to_buffer & ~transfer_out) begin
            // store incoming data while not transferring out
            buf_data  <= data_in;
            buf_valid <= 1'b1;
        end else if (transfer_out) begin
            // if we transfer out, clear buffer valid if no new load
            buf_valid <= load_to_buffer ? 1'b1 : 1'b0;
            if (load_to_buffer)
                buf_data <= data_in;
        end
    end

    assign ready_out = ~buf_valid | transfer_out;
    assign valid_out = buf_valid | (valid_in & ready_out & ~buf_valid);
    assign data_out  = buf_valid ? buf_data : data_in;

endmodule

// stream_join: waits for both inputs to be valid together, then produces output
// Implements ready/valid handshake on all interfaces

module stream_join #(
    parameter DATA_WIDTH = 8
) (
    input  wire                    clk,
    input  wire                    rst_n,
    input  wire [DATA_WIDTH-1:0]   data_in0,
    input  wire                    valid_in0,
    output wire                    ready_out0,
    input  wire [DATA_WIDTH-1:0]   data_in1,
    input  wire                    valid_in1,
    output wire                    ready_out1,
    output wire [DATA_WIDTH-1:0]   data_out,
    output wire                    valid_out,
    input  wire                    ready_in
);

    reg [DATA_WIDTH-1:0] join_data_reg;
    reg                  join_valid_reg;

    wire fire = valid_in0 & valid_in1 & ready_in;
    wire load = fire;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            join_data_reg  <= {DATA_WIDTH{1'b0}};
            join_valid_reg <= 1'b0;
        end else if (load) begin
            join_data_reg  <= data_in0 + data_in1;
            join_valid_reg <= 1'b1;
        end else if (ready_in & join_valid_reg) begin
            join_valid_reg <= 1'b0;
        end
    end

    assign ready_out0 = ready_in;
    assign ready_out1 = ready_in;
    assign data_out   = join_data_reg;
    assign valid_out  = join_valid_reg;

endmodule

// stream_stage: a simple pipeline register with valid-ready handshake

module stream_stage #(
    parameter DATA_WIDTH = 8
) (
    input  wire                    clk,
    input  wire                    rst_n,
    input  wire [DATA_WIDTH-1:0]   data_in,
    input  wire                    valid_in,
    output wire                    ready_out,
    output wire [DATA_WIDTH-1:0]   data_out,
    output wire                    valid_out,
    input  wire                    ready_in
);

    reg [DATA_WIDTH-1:0] stage_data;
    reg                  stage_valid;

    wire load = valid_in & ready_out;
    wire transfer_out = stage_valid & ready_in;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            stage_data  <= {DATA_WIDTH{1'b0}};
            stage_valid <= 1'b0;
        end else if (load) begin
            stage_data  <= data_in;
            stage_valid <= 1'b1;
        end else if (transfer_out) begin
            stage_valid <= 1'b0;
        end
    end

    assign ready_out = ~stage_valid | transfer_out;
    assign data_out  = stage_data;
    assign valid_out = stage_valid;

endmodule

// top module: dual-stream join with accumulation
// Generated from System-HIS v1.2

