`timescale 1ns / 1ps

// Accumulator core: adds input to internal register modulo 256
module accumulator_core #(
  parameter DATA_WIDTH = 8
) (
  input  wire                clk,
  input  wire                rst_n,
  input  wire                in_valid,
  output wire                in_ready,
  input  wire [DATA_WIDTH-1:0] in_data,
  output wire                out_valid,
  input  wire                out_ready,
  output wire [DATA_WIDTH-1:0] out_data
);

  reg [DATA_WIDTH-1:0] acc_reg;
  reg acc_valid;

  wire transfer_in = in_valid & in_ready;
  wire transfer_out = acc_valid & out_ready;

  assign in_ready = out_ready | ~acc_valid;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      acc_reg <= 0;
      acc_valid <= 1'b0;
    end else begin
      if (transfer_out) begin
        acc_valid <= 1'b0;
      end
      if (transfer_in & (transfer_out | ~acc_valid)) begin
        acc_reg <= acc_reg + in_data;
        acc_valid <= 1'b1;
      end
    end
  end

  assign out_valid = acc_valid;
  assign out_data = acc_reg;

endmodule

`timescale 1ns / 1ps

// Skid buffer: enables one word of storage to decouple handshake
module skid_buffer #(
  parameter DATA_WIDTH = 8
) (
  input  wire                clk,
  input  wire                rst_n,
  input  wire                in_valid,
  output wire                in_ready,
  input  wire [DATA_WIDTH-1:0] in_data,
  output wire                out_valid,
  input  wire                out_ready,
  output wire [DATA_WIDTH-1:0] out_data
);

  // Skid buffer implementation
  reg skid_valid;
  reg [DATA_WIDTH-1:0] skid_data;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      skid_valid <= 1'b0;
    end else begin
      if (in_ready) begin
        skid_valid <= 1'b0;
      end else if (in_valid) begin
        skid_valid <= 1'b1;
        skid_data <= in_data;
      end
    end
  end

  // combinational
  assign in_ready = ~skid_valid | out_ready;
  assign out_valid = skid_valid | (in_valid & ~skid_valid);
  assign out_data = (skid_valid) ? skid_data : in_data;

endmodule

`timescale 1ns / 1ps

// Stream join: waits for both inputs valid, then outputs sum modulo 256
module stream_join #(
  parameter DATA_WIDTH = 8
) (
  input  wire                clk,
  input  wire                rst_n,
  input  wire                in0_valid,
  output wire                in0_ready,
  input  wire [DATA_WIDTH-1:0] in0_data,
  input  wire                in1_valid,
  output wire                in1_ready,
  input  wire [DATA_WIDTH-1:0] in1_data,
  output wire                out_valid,
  input  wire                out_ready,
  output wire [DATA_WIDTH-1:0] out_data
);

  // Simple implementation: combinational sum when both valid
  assign in0_ready = out_ready | ~out_valid;
  assign in1_ready = out_ready | ~out_valid;
  // Need registered output for proper handshake with backpressure
  reg [DATA_WIDTH-1:0] sum_reg;
  reg sum_valid;

  wire both_valid = in0_valid & in1_valid;
  wire transfer = sum_valid & out_ready;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      sum_valid <= 1'b0;
      sum_reg <= 0;
    end else begin
      if (transfer) begin
        sum_valid <= 1'b0;
      end
      if (both_valid & (transfer | ~sum_valid)) begin
        sum_valid <= 1'b1;
        sum_reg <= in0_data + in1_data;
      end
    end
  end

  assign out_valid = sum_valid;
  assign out_data = sum_reg;

endmodule

`timescale 1ns / 1ps

// Pipeline stage with valid-ready handshake
module stream_stage #(
  parameter DATA_WIDTH = 8
) (
  input  wire                clk,
  input  wire                rst_n,
  input  wire                in_valid,
  output wire                in_ready,
  input  wire [DATA_WIDTH-1:0] in_data,
  output wire                out_valid,
  input  wire                out_ready,
  output wire [DATA_WIDTH-1:0] out_data
);

  reg [DATA_WIDTH-1:0] pipe_reg;
  reg pipe_valid;

  wire transfer_in = in_valid & in_ready;
  wire transfer_out = pipe_valid & out_ready;

  assign in_ready = out_ready | ~pipe_valid;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pipe_reg <= 0;
      pipe_valid <= 1'b0;
    end else begin
      if (transfer_out) begin
        pipe_valid <= 1'b0;
      end
      if (transfer_in & (transfer_out | ~pipe_valid)) begin
        pipe_reg <= in_data;
        pipe_valid <= 1'b1;
      end
    end
  end

  assign out_valid = pipe_valid;
  assign out_data = pipe_reg;

endmodule

