  // Instantiate stream_stage
  stream_stage #(
    .DATA_WIDTH(DATA_WIDTH)
  ) out_stage (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(acc_out_valid),
    .in_ready(stage_in_ready),
    .in_data(acc_out_data),
    .out_valid(out_valid),
    .out_ready(out_ready),
    .out_data(out_data)
