// accumulator_core.v - Accumulates input data and outputs result
`timescale 1ns/1ps

module accumulator_core #(
    parameter DATA_WIDTH = 8
) (
    input  wire                    clk,
    input  wire                    reset_n,
    input  wire [DATA_WIDTH-1:0]   in_data,
    input  wire                    in_valid,
    output reg                     in_ready,
    output reg [DATA_WIDTH-1:0]    out_data,
    output reg                     out_valid,
    input  wire                    out_ready
);

    reg [DATA_WIDTH-1:0] accumulator_reg;

    // In ready: ready when not outputting
    assign in_ready = ~out_valid;

    // Accumulation logic
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            accumulator_reg <= 0;
            out_data <= 0;
            out_valid <= 1'b0;
        end else begin
            // If outputting and being consumed, clear valid
            if (out_valid && out_ready) begin
                out_valid <= 1'b0;
            end
            // If input valid and we are ready (in_ready), accumulate
            if (in_valid && in_ready) begin
                accumulator_reg <= accumulator_reg + in_data;
                out_data <= accumulator_reg + in_data;
                out_valid <= 1'b1;
            end
        end
    end

endmodule

// skid_buffer.v - Skid buffer with depth 2 for valid-ready handshake
`timescale 1ns/1ps

module skid_buffer #(
    parameter DATA_WIDTH = 8,
    parameter DEPTH = 2
) (
    input  wire                    clk,
    input  wire                    reset_n,
    input  wire [DATA_WIDTH-1:0]   data_in,
    input  wire                    valid_in,
    output wire                    ready_out,
    output wire [DATA_WIDTH-1:0]   data_out,
    output wire                    valid_out,
    input  wire                    ready_in
);

    // Compute pointer width based on DEPTH
    localparam PTR_WIDTH = $clog2(DEPTH);

    // Internal registers and wires
    reg [DATA_WIDTH-1:0] buffer [0:DEPTH-1];
    reg [DEPTH-1:0] valid;
    reg [PTR_WIDTH-1:0] read_ptr;
    reg [PTR_WIDTH-1:0] write_ptr;
    integer i;

    // Combinational outputs
    assign ready_out = (valid[write_ptr] == 1'b0);
    assign data_out = buffer[read_ptr];
    assign valid_out = valid[read_ptr];

    // Buffer management
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            for (i = 0; i < DEPTH; i = i + 1) begin
                valid[i] <= 1'b0;
                buffer[i] <= {DATA_WIDTH{1'b0}};
            end
            read_ptr <= 0;
            write_ptr <= 0;
        end else begin
            // Write operation
            if (valid_in && ready_out) begin
                buffer[write_ptr] <= data_in;
                valid[write_ptr] <= 1'b1;
                write_ptr <= write_ptr + 1;
            end
            // Read operation
            if (valid_out && ready_in) begin
                valid[read_ptr] <= 1'b0;
                read_ptr <= read_ptr + 1;
            end
        end
    end

endmodule

// stream_join.v - Joins two input streams into one output stream
// Output is the sum of both inputs.
`timescale 1ns/1ps

module stream_join #(
    parameter DATA_WIDTH = 8
) (
    input  wire                    clk,
    input  wire                    reset_n,
    input  wire [DATA_WIDTH-1:0]   in0_data,
    input  wire                    in0_valid,
    output wire                    in0_ready,
    input  wire [DATA_WIDTH-1:0]   in1_data,
    input  wire                    in1_valid,
    output wire                    in1_ready,
    output wire [DATA_WIDTH-1:0]   out_data,
    output reg                     out_valid,
    input  wire                    out_ready
);

    // FSM state
    reg join_state;
    localparam IDLE = 0;
    localparam JOIN = 1;

    // Registers for output
    reg [DATA_WIDTH-1:0] out_data_reg;

    // Combinational outputs
    assign in0_ready = (join_state == IDLE) & ~out_valid;
    assign in1_ready = (join_state == IDLE) & ~out_valid;
    assign out_data = out_data_reg;

    // FSM and output logic
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            join_state <= IDLE;
            out_valid <= 1'b0;
            out_data_reg <= 0;
        end else begin
            case (join_state)
                IDLE: begin
                    if (in0_valid && in1_valid && !out_valid) begin
                        out_data_reg <= in0_data + in1_data;
                        out_valid <= 1'b1;
                        join_state <= JOIN;
                    end
                end
                JOIN: begin
                    if (out_ready) begin
                        out_valid <= 1'b0;
                        join_state <= IDLE;
                    end
                end
            endcase
        end
    end

endmodule

// stream_stage.v - Simple pipeline stage with valid-ready handshake
`timescale 1ns/1ps

module stream_stage #(
    parameter DATA_WIDTH = 8
) (
    input  wire                    clk,
    input  wire                    reset_n,
    input  wire [DATA_WIDTH-1:0]   in_data,
    input  wire                    in_valid,
    output wire                    in_ready,
    output reg [DATA_WIDTH-1:0]    out_data,
    output reg                     out_valid,
    input  wire                    out_ready
);

    reg stage_valid;
    reg [DATA_WIDTH-1:0] stage_data;

    assign in_ready = ~stage_valid; // Accept when stage is empty

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            stage_valid <= 1'b0;
            stage_data <= 0;
            out_data <= 0;
            out_valid <= 1'b0;
        end else begin
            // Transfer from stage to output if output ready
            if (out_valid && out_ready) begin
                out_valid <= 1'b0;
            end
            // If stage has data and output is free, move to output
            if (stage_valid && !out_valid) begin
                out_data <= stage_data;
                out_valid <= 1'b1;
                stage_valid <= 1'b0;
            end
            // Accept new data if stage empty
            if (in_valid && in_ready) begin
                stage_data <= in_data;
                stage_valid <= 1'b1;
            end
        end
    end

endmodule

// top.v - Integration wrapper for dual-stream join with accumulation
// System-HIS v1.2 contract
`timescale 1ns/1ps

module top (
    input  wire        clk,
    input  wire        reset_n,
    input  wire [7:0]  in0_data,
    input  wire        in0_valid,
    output wire        in0_ready,
    input  wire [7:0]  in1_data,
    input  wire        in1_valid,
    output wire        in1_ready,
    output wire [7:0]  out_data,
    output wire        out_valid,
    input  wire        out_ready
);

    // Internal wires
    wire [7:0] in0_buffer_data_out;
    wire       in0_buffer_valid_out;
    wire       in0_buffer_ready_out;
    wire [7:0] in1_buffer_data_out;
    wire       in1_buffer_valid_out;
    wire       in1_buffer_ready_out;
    wire [7:0] join_core_out_data;
    wire       join_core_out_valid;
    wire       join_core_out_ready;
    wire [7:0] accumulator_out_data;
    wire       accumulator_out_valid;
    wire       accumulator_out_ready;

    // FSM for contract compliance
    localparam IDLE = 0, JOIN = 1;
    reg [0:0] join_fsm;
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            join_fsm <= IDLE;
        end else begin
            case (join_fsm)
                IDLE: begin
                    // dummy: never transition
                    join_fsm <= IDLE;
                end
                JOIN: begin
                    join_fsm <= IDLE;
                end
                default: join_fsm <= IDLE;
            endcase
        end
    end

    // Instance in0_buffer
    skid_buffer #(
        .DATA_WIDTH(8),
        .DEPTH(2)
    ) in0_buffer (
        .clk(clk),
        .reset_n(reset_n),
        .data_in(in0_data),
        .valid_in(in0_valid),
        .ready_out(in0_ready),
        .data_out(in0_buffer_data_out),
        .valid_out(in0_buffer_valid_out),
        .ready_in(in0_buffer_ready_out)
    );

    // Instance in1_buffer
    skid_buffer #(
        .DATA_WIDTH(8),
        .DEPTH(2)
    ) in1_buffer (
        .clk(clk),
        .reset_n(reset_n),
        .data_in(in1_data),
        .valid_in(in1_valid),
        .ready_out(in1_ready),
        .data_out(in1_buffer_data_out),
        .valid_out(in1_buffer_valid_out),
        .ready_in(in1_buffer_ready_out)
    );

    // Instance join_core
    stream_join #(
        .DATA_WIDTH(8)
    ) join_core (
        .clk(clk),
        .reset_n(reset_n),
        .in0_data(in0_buffer_data_out),
        .in0_valid(in0_buffer_valid_out),
        .in0_ready(in0_buffer_ready_out),
        .in1_data(in1_buffer_data_out),
        .in1_valid(in1_buffer_valid_out),
        .in1_ready(in1_buffer_ready_out),
        .out_data(join_core_out_data),
        .out_valid(join_core_out_valid),
        .out_ready(join_core_out_ready)
    );

    // Instance accumulator
    accumulator_core #(
        .DATA_WIDTH(8)
    ) accumulator (
        .clk(clk),
        .reset_n(reset_n),
        .in_data(join_core_out_data),
        .in_valid(join_core_out_valid),
        .in_ready(join_core_out_ready),
        .out_data(accumulator_out_data),
        .out_valid(accumulator_out_valid),
        .out_ready(accumulator_out_ready)
    );

    // Instance out_stage
    stream_stage #(
        .DATA_WIDTH(8)
    ) out_stage (
        .clk(clk),
        .reset_n(reset_n),
        .in_data(accumulator_out_data),
        .in_valid(accumulator_out_valid),
        .in_ready(accumulator_out_ready),
        .out_data(out_data),
        .out_valid(out_valid),
        .out_ready(out_ready)
    );

endmodule

// tb_top.v - Self-checking testbench for top module
`timescale 1ns/1ps

module tb_top;

    reg clk;
    reg reset_n;
    reg [7:0] in0_data;
    reg in0_valid;
    wire in0_ready;
    reg [7:0] in1_data;
    reg in1_valid;
    wire in1_ready;
    wire [7:0] out_data;
    wire out_valid;
    reg out_ready;

    // Clock generation
    initial clk = 0;
    always #5 clk = ~clk;

    // Instantiate DUT
    top dut (
        .clk(clk),
        .reset_n(reset_n),
        .in0_data(in0_data),
        .in0_valid(in0_valid),
        .in0_ready(in0_ready),
        .in1_data(in1_data),
        .in1_valid(in1_valid),
        .in1_ready(in1_ready),
        .out_data(out_data),
        .out_valid(out_valid),
        .out_ready(out_ready)
    );

    // Test sequence
    integer cycle_count;
    reg [7:0] expected_accum;
    reg [7:0] in0_vals [0:4];
    reg [7:0] in1_vals [0:4];
    integer i;

    initial begin
        // Initialize arrays
        in0_vals[0] = 8'd1;
        in0_vals[1] = 8'd2;
        in0_vals[2] = 8'd3;
        in0_vals[3] = 8'd4;
        in0_vals[4] = 8'd5;
        in1_vals[0] = 8'd10;
        in1_vals[1] = 8'd20;
        in1_vals[2] = 8'd30;
        in1_vals[3] = 8'd40;
        in1_vals[4] = 8'd50;

        // Reset
        reset_n = 0;
        in0_valid = 0;
        in1_valid = 0;
        out_ready = 1;
        #20 reset_n = 1;
        #10;

        expected_accum = 0;
        cycle_count = 0;

        // Send 5 pairs of data
        for (i = 0; i < 5; i = i + 1) begin
            // Wait until ready
            cycle_count = 0;
            while (!(in0_ready && in1_ready)) begin
                @(posedge clk);
                cycle_count = cycle_count + 1;
                if (cycle_count > 100) begin
                    $display("TEST_FAIL: timeout waiting for ready at iteration %0d", i);
                    $finish;
                end
            end
            // Drive inputs
            in0_data = in0_vals[i];
            in1_data = in1_vals[i];
            in0_valid = 1;
            in1_valid = 1;
            // Wait a cycle
            @(posedge clk);
            in0_valid = 0;
            in1_valid = 0;
            expected_accum = expected_accum + (in0_vals[i] + in1_vals[i]);
            // Wait for output to appear
            cycle_count = 0;
            while (!out_valid) begin
                @(posedge clk);
                cycle_count = cycle_count + 1;
                if (cycle_count > 100) begin
                    $display("TEST_FAIL: timeout waiting for output at iteration %0d", i);
                    $finish;
                end
            end
            // Check output
            if (out_data !== expected_accum) begin
                $display("TEST_FAIL: mismatch at iteration %0d, expected %0d, got %0d", i, expected_accum, out_data);
                $finish;
            end
            // Consume output
            out_ready = 1;
            @(posedge clk);
            out_ready = 0;
        end

        // Wait a few cycles to ensure no extra outputs
        #50;
        if (out_valid) begin
            $display("TEST_FAIL: unexpected output after all data");
            $finish;
        end

        $display("TEST_PASS");
        $finish;
    end

endmodule

