module accumulator_core #(
    parameter DATA_WIDTH = 8
)(
    input  wire                clk,
    input  wire                reset_n,
    input  wire [DATA_WIDTH-1:0] in_data,
    input  wire                in_valid,
    input  wire                out_ready,
    output reg  [DATA_WIDTH-1:0] out_data,
    output reg                 out_valid,
    output wire                in_ready
);

    reg [DATA_WIDTH-1:0] acc_reg;
    reg [DATA_WIDTH-1:0] next_acc;
    reg next_valid;

    always @(posedge clk) begin
        if (!reset_n) begin
            acc_reg   <= {DATA_WIDTH{1'b0}};
            out_data  <= {DATA_WIDTH{1'b0}};
            out_valid <= 1'b0;
        end else begin
            // Update accumulator when input is accepted
            if (in_valid && in_ready) begin
                acc_reg <= acc_reg + in_data;
            end
            // Output register
            if (out_valid && out_ready) begin
                out_valid <= 1'b0;
            end
            if (next_valid) begin
                out_data  <= next_acc;
                out_valid <= 1'b1;
            end
        end
    end

    assign in_ready = !out_valid || out_ready;  // Can accept if output not valid or downstream ready

    // Next state combinational
    always @(*) begin
        if (in_valid && in_ready) begin
            next_acc   = acc_reg + in_data;
            next_valid = 1'b1;
        end else begin
            next_acc   = acc_reg;
            next_valid = 1'b0;
        end
    end

endmodule

`timescale 1ns / 1ps

module skid_buffer #(
    parameter DATA_WIDTH = 8
)(
    input  wire                clk,
    input  wire                reset_n,
    input  wire [DATA_WIDTH-1:0] in_data,
    input  wire                in_valid,
    input  wire                out_ready,
    output reg  [DATA_WIDTH-1:0] out_data,
    output reg                 out_valid,
    output wire                in_ready
);

    // Depth 2 skid buffer
    reg [DATA_WIDTH-1:0] buf0, buf1;
    reg empty, full;
    reg rd_ptr; // 0 = buf0, 1 = buf1

    always @(posedge clk) begin
        if (!reset_n) begin
            out_valid <= 1'b0;
            out_data  <= {DATA_WIDTH{1'b0}};
            buf0      <= {DATA_WIDTH{1'b0}};
            buf1      <= {DATA_WIDTH{1'b0}};
            empty     <= 1'b1;
            full      <= 1'b0;
            rd_ptr    <= 1'b0;
        end else begin
            // Write operation
            if (in_valid && in_ready) begin
                if (empty) begin
                    // Buffer empty: write directly to output register
                    out_data  <= in_data;
                    out_valid <= 1'b1;
                    empty     <= 1'b0;
                    full      <= 1'b0;
                end else if (!full) begin
                    // Buffer non-empty but not full: write to next slot
                    if (rd_ptr == 0) begin
                        buf1 <= in_data;
                        full <= 1'b1;
                    end else begin
                        buf0 <= in_data;
                        full <= 1'b1;
                    end
                end else begin
                    // Full: drop (should not happen if in_ready is deasserted when full)
                end
            end

            // Read operation (output consumed)
            if (out_valid && out_ready) begin
                if (full) begin
                    // There is a buffered sample
                    if (rd_ptr == 0) begin
                        out_data <= buf0;
                    end else begin
                        out_data <= buf1;
                    end
                    out_valid <= 1'b1;
                    full      <= 1'b0;
                    rd_ptr    <= ~rd_ptr;
                end else begin
                    out_valid <= 1'b0;
                    empty     <= 1'b1;
                end
            end
        end
    end

    assign in_ready = !full;

endmodule

`timescale 1ns / 1ps

module stream_join #(
    parameter DATA_WIDTH = 8
)(
    input  wire                clk,
    input  wire                reset_n,
    input  wire [DATA_WIDTH-1:0] in0_data,
    input  wire                in0_valid,
    output reg                 in0_ready,
    /* verilator lint_off UNUSEDSIGNAL */
    input  wire [DATA_WIDTH-1:0] in1_data,
    /* verilator lint_on UNUSEDSIGNAL */
    input  wire                in1_valid,
    output reg                 in1_ready,
    output reg  [DATA_WIDTH-1:0] out_data,
    output reg                 out_valid,
    input  wire                out_ready
);

    // When both inputs are valid and we can accept (in0_ready & in1_ready high), capture data.
    // Output one cycle later if out_ready is high or we can hold.
    reg [DATA_WIDTH-1:0] held_data;
    reg held_valid;

    always @(posedge clk) begin
        if (!reset_n) begin
            in0_ready   <= 1'b0;
            in1_ready   <= 1'b0;
            held_data   <= {DATA_WIDTH{1'b0}};
            held_valid  <= 1'b0;
            out_data    <= {DATA_WIDTH{1'b0}};
            out_valid   <= 1'b0;
        end else begin
            // Default: ready when we can accept new data (not holding or output consumed)
            if (!held_valid || (out_valid && out_ready)) begin
                in0_ready <= 1'b1;
                in1_ready <= 1'b1;
            end else begin
                in0_ready <= 1'b0;
                in1_ready <= 1'b0;
            end

            // Input capture
            if (in0_ready && in1_ready && in0_valid && in1_valid) begin
                if (out_valid && out_ready) begin
                    // Output consumed this cycle, so we can output directly
                    out_data  <= in0_data;  // forward in0_data as joined data
                    out_valid <= 1'b1;
                    held_valid <= 1'b0;
                end else begin
                    // Hold for next cycle
                    held_data  <= in0_data;
                    held_valid <= 1'b1;
                    out_valid  <= 1'b0;
                end
            end else begin
                // If holding and output ready, output held data
                if (held_valid && out_ready) begin
                    out_data  <= held_data;
                    out_valid <= 1'b1;
                    held_valid <= 1'b0;
                end else if (!held_valid) begin
                    out_valid <= 1'b0;
                end
            end
        end
    end

endmodule

`timescale 1ns / 1ps

module stream_stage #(
    parameter DATA_WIDTH = 8
)(
    input  wire                clk,
    input  wire                reset_n,
    input  wire [DATA_WIDTH-1:0] in_data,
    input  wire                in_valid,
    input  wire                out_ready,
    output reg  [DATA_WIDTH-1:0] out_data,
    output reg                 out_valid,
    output wire                in_ready
);

    reg [DATA_WIDTH-1:0] pipe_data;
    reg pipe_valid;

    always @(posedge clk) begin
        if (!reset_n) begin
            pipe_data  <= {DATA_WIDTH{1'b0}};
            pipe_valid <= 1'b0;
            out_data   <= {DATA_WIDTH{1'b0}};
            out_valid  <= 1'b0;
        end else begin
            // Input stage: capture if valid and we are ready
            if (in_valid && in_ready) begin
                pipe_data  <= in_data;
                pipe_valid <= 1'b1;
            end else begin
                if (out_valid && out_ready) begin
                    pipe_valid <= 1'b0;
                end
            end
            // Output stage: if pipe has data, output it
            if (pipe_valid && (!out_valid || out_ready)) begin
                out_data  <= pipe_data;
                out_valid <= 1'b1;
                pipe_valid <= 1'b0;
            end else if (out_valid && out_ready) begin
                out_valid <= 1'b0;
            end
        end
    end

    assign in_ready = !pipe_valid || (out_valid && out_ready);  // Can accept if pipeline empty or output consumed

endmodule

`timescale 1ns / 1ps

module top #(
    parameter DATA_WIDTH = 8
)(
    input  wire                clk,
    input  wire                reset_n,
    input  wire [DATA_WIDTH-1:0] in0_data,
    input  wire                in0_valid,
    output wire                in0_ready,
    input  wire [DATA_WIDTH-1:0] in1_data,
    input  wire                in1_valid,
    output wire                in1_ready,
    output wire [DATA_WIDTH-1:0] out_data,
    output wire                out_valid,
    input  wire                out_ready
);

    // Internal wires
    wire [DATA_WIDTH-1:0] buf0_out_data;
    wire buf0_out_valid;
    wire [DATA_WIDTH-1:0] buf1_out_data;
    wire buf1_out_valid;
    wire [DATA_WIDTH-1:0] join_out_data;
    wire join_out_valid;
    wire join_in0_ready, join_in1_ready;
    wire [DATA_WIDTH-1:0] acc_out_data;
    wire acc_out_valid;
    wire acc_in_ready;
    wire stage_in_ready;

    // Instantiations
    skid_buffer #(
        .DATA_WIDTH(DATA_WIDTH)
    ) in0_buffer (
        .clk(clk),
        .reset_n(reset_n),
        .in_data(in0_data),
        .in_valid(in0_valid),
        .out_ready(join_in0_ready),
        .out_data(buf0_out_data),
        .out_valid(buf0_out_valid),
        .in_ready(in0_ready)
    );

    skid_buffer #(
        .DATA_WIDTH(DATA_WIDTH)
    ) in1_buffer (
        .clk(clk),
        .reset_n(reset_n),
        .in_data(in1_data),
        .in_valid(in1_valid),
        .out_ready(join_in1_ready),
        .out_data(buf1_out_data),
        .out_valid(buf1_out_valid),
        .in_ready(in1_ready)
    );

    stream_join #(
        .DATA_WIDTH(DATA_WIDTH)
    ) join_core (
        .clk(clk),
        .reset_n(reset_n),
        .in0_data(buf0_out_data),
        .in0_valid(buf0_out_valid),
        .in0_ready(join_in0_ready),
        .in1_data(buf1_out_data),
        .in1_valid(buf1_out_valid),
        .in1_ready(join_in1_ready),
        .out_data(join_out_data),
        .out_valid(join_out_valid),
        .out_ready(acc_in_ready)
    );

    accumulator_core #(
        .DATA_WIDTH(DATA_WIDTH)
    ) accumulator (
        .clk(clk),
        .reset_n(reset_n),
        .in_data(join_out_data),
        .in_valid(join_out_valid),
        .out_ready(stage_in_ready),
        .out_data(acc_out_data),
        .out_valid(acc_out_valid),
        .in_ready(acc_in_ready)
    );

    stream_stage #(
        .DATA_WIDTH(DATA_WIDTH)
    ) out_stage (
        .clk(clk),
        .reset_n(reset_n),
        .in_data(acc_out_data),
        .in_valid(acc_out_valid),
        .out_ready(out_ready),
        .out_data(out_data),
        .out_valid(out_valid),
        .in_ready(stage_in_ready)
    );

endmodule

