`timescale 1ns / 1ps
module accumulator_core #(
  parameter WIDTH = 8
) (
  input  wire              clk,
  input  wire              rst_n,
  input  wire              s_valid,
  output wire              s_ready,
  input  wire [WIDTH-1:0]  s_data,
  output wire              m_valid,
  input  wire              m_ready,
  output wire [WIDTH-1:0]  m_data
);

  // Accumulator register (9 bits to handle overflow)
  reg [WIDTH:0] accum_reg;

  // Output register
  reg [WIDTH-1:0] out_data_reg;
  reg out_valid_reg;

  // Ready is always asserted since we can accept data every cycle
  assign s_ready = 1'b1;
  assign m_valid = out_valid_reg;
  assign m_data = out_data_reg;

  always @(posedge clk) begin
    if (!rst_n) begin
      accum_reg <= 9'b0;
      out_data_reg <= {WIDTH{1'b0}};
      out_valid_reg <= 1'b0;
    end else begin
      // Update accumulator when input is valid
      if (s_valid) begin
        accum_reg <= accum_reg + {1'b0, s_data};
      end

      // Update output register
      out_data_reg <= accum_reg[WIDTH-1:0];
      // Valid follows the accumulator update (after first sample)
      if (s_valid) begin
        out_valid_reg <= 1'b1;
      end else if (m_ready) begin
        out_valid_reg <= 1'b0;
      end
    end
  end

endmodule

`timescale 1ns / 1ps
module skid_buffer #(
  parameter WIDTH = 8
) (
  input  wire              clk,
  input  wire              rst_n,
  input  wire              s_valid,
  output wire              s_ready,
  input  wire [WIDTH-1:0]  s_data,
  output wire              m_valid,
  input  wire              m_ready,
  output wire [WIDTH-1:0]  m_data
);

  // Skid buffer storage
  reg [WIDTH-1:0] buffer_data;
  reg             buffer_valid;

  // Output assignment
  assign s_ready = m_ready | ~buffer_valid;
  assign m_valid = buffer_valid | s_valid;
  assign m_data = buffer_valid ? buffer_data : s_data;

  always @(posedge clk) begin
    if (!rst_n) begin
      buffer_data <= {WIDTH{1'b0}};
      buffer_valid <= 1'b0;
    end else begin
      if (m_ready && buffer_valid) begin
        // Output consumed, replace with new data if available
        if (s_valid) begin
          buffer_data <= s_data;
        end else begin
          buffer_valid <= 1'b0;
        end
      end else if (m_ready && !buffer_valid && s_valid) begin
        // No buffered data, but new data available
        buffer_data <= s_data;
        buffer_valid <= 1'b1;
      end else if (!m_ready && s_valid && !buffer_valid) begin
        // Backpressure, store incoming data
        buffer_data <= s_data;
        buffer_valid <= 1'b1;
      end
    end
  end

endmodule

`timescale 1ns / 1ps
module qwen_smoke_t2_stream_accumulator_8_000001 #(
  parameter DATA_WIDTH = 8
) (
  input  wire         clk,
  input  wire         rst_n,
  input  wire         s_axis_valid,
