            expected1[count_sent] = in_data;
            count_sent = count_sent + 1;
            in_valid = 0;
            @(posedge clk);
        end
        repeat(100) @(posedge clk);
        if (errors == 0 && count_recv0 == count_sent && count_recv1 == count_sent) begin
