module accumulator_core #(parameter W=8) (
    input clk, rst_n,
    input sample_valid, input [W-1:0] sample,
    output reg sample_ready,
    output reg sum_valid, output reg [W-1:0] sum,
    input sum_ready
);
    reg [W-1:0] acc;
    reg state;
    localparam IDLE = 0, HOLD = 1;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            acc <= 0;
            sum_valid <= 0;
            sample_ready <= 1;
            state <= IDLE;
        end else begin
            case(state)
                IDLE: begin
                    sample_ready <= 1;
                    if (sample_valid) begin
                        acc <= acc + sample;
                        sum <= acc + sample;
                        sum_valid <= 1;
                        state <= HOLD;
                        sample_ready <= 0;
                    end else begin
                        sum_valid <= 0;
                    end
                end
                HOLD: begin
                    sample_ready <= 0;
                    if (sum_ready) begin
                        state <= IDLE;
                        sum_valid <= 0;
                    end
                end
            endcase
        end
    end
endmodule

module skid_buffer #(parameter W=8) (
    input clk, rst_n,
    input in_valid, input [W-1:0] in_data,
    output reg in_ready,
    output reg out_valid, output reg [W-1:0] out_data,
    input out_ready
);
    reg [W-1:0] buf_data;
    reg buf_valid;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid <= 0;
            buf_valid <= 0;
            in_ready <= 1;
        end else begin
            if (out_valid && out_ready) begin
                if (buf_valid) begin
                    out_data <= buf_data;
                    buf_valid <= 0;
                    in_ready <= 1;
                end else begin
                    out_valid <= 0;
                    in_ready <= 1;
                end
            end else if (!out_valid && in_valid) begin
                out_valid <= 1;
                out_data <= in_data;
                in_ready <= 1;
            end else if (out_valid && !out_ready && in_valid) begin
                buf_valid <= 1;
                buf_data <= in_data;
                in_ready <= 0;
            end
        end
    end
endmodule

module stream_join #(parameter W=8) (
    input clk, rst_n,
    input in0_valid, input [W-1:0] in0_data,
    output reg in0_ready,
    input in1_valid, input [W-1:0] in1_data,
    output reg in1_ready,
    output reg out_valid, output reg [W-1:0] out_data,
    input out_ready
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid <= 0;
            in0_ready <= 1;
            in1_ready <= 1;
        end else begin
            if (!out_valid || out_ready) begin
                if (in0_valid && in1_valid) begin
                    out_valid <= 1;
                    out_data <= in0_data + in1_data;
                    in0_ready <= 1;
                    in1_ready <= 1;
                end else begin
                    out_valid <= 0;
                    in0_ready <= 1;
                    in1_ready <= 1;
                end
            end else begin
                in0_ready <= 0;
                in1_ready <= 0;
            end
        end
    end
endmodule

module stream_stage #(parameter W=8) (
