module dot_product_engine #(
    parameter WIDTH = 8,
    parameter RESULT_WIDTH = 12
) (
    input wire clk,
    input wire rst_n,
    input wire start,
    output reg busy,
    output reg done,
    output reg [RESULT_WIDTH-1:0] result
);

  reg [1:0] index;
  reg [RESULT_WIDTH-1:0] accum;
  reg [WIDTH-1:0] vector_value;
  wire [1:0] coefficient;
  wire [RESULT_WIDTH-1:0] next_accum;

  vector_rom u_vector_rom (
    .addr(index),
    .coefficient(coefficient)
  );

  mac_unit #(
    .WIDTH(WIDTH),
    .ACC_WIDTH(RESULT_WIDTH)
  ) u_mac_unit (
    .sample(vector_value),
    .coefficient(coefficient),
    .accum(accum),
    .result(next_accum)
  );

  always @* begin
    case (index)
      2'd0: vector_value = {{(WIDTH-1){1'b0}}, 1'b1};
      2'd1: vector_value = {{(WIDTH-2){1'b0}}, 2'd2};
      2'd2: vector_value = {{(WIDTH-2){1'b0}}, 2'd3};
      default: vector_value = {{(WIDTH-3){1'b0}}, 3'd4};
    endcase
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      index <= 2'd0;
      accum <= {RESULT_WIDTH{1'b0}};
      busy <= 1'b0;
      done <= 1'b0;
      result <= {RESULT_WIDTH{1'b0}};
    end else begin
      done <= 1'b0;
      if (!busy) begin
        index <= 2'd0;
        accum <= {RESULT_WIDTH{1'b0}};
        if (start) begin
          busy <= 1'b1;
        end
      end else begin
        accum <= next_accum;
        if (index == 2'd3) begin
          result <= next_accum;
          busy <= 1'b0;
          done <= 1'b1;
          index <= 2'd0;
        end else begin
          index <= index + 2'd1;
        end
      end
    end
  end

endmodule

module mac_unit #(
    parameter WIDTH = 8,
    parameter ACC_WIDTH = 12
) (
    input wire [WIDTH-1:0] sample,
    input wire [1:0] coefficient,
    input wire [ACC_WIDTH-1:0] accum,
    output wire [ACC_WIDTH-1:0] result
);

  wire [ACC_WIDTH-1:0] extended_sample;
  wire [ACC_WIDTH-1:0] product_x1;
  wire [ACC_WIDTH-1:0] product_x2;

  assign extended_sample = {{(ACC_WIDTH-WIDTH){1'b0}}, sample};
  assign product_x1 = coefficient[0] ? extended_sample : {ACC_WIDTH{1'b0}};
  assign product_x2 = coefficient[1] ? (extended_sample << 1) : {ACC_WIDTH{1'b0}};
  assign result = accum + product_x1 + product_x2;

endmodule

module vector_rom (
    input wire [1:0] addr,
    output reg [1:0] coefficient
);

  always @* begin
    case (addr)
      2'd0: coefficient = 2'd2;
      2'd1: coefficient = 2'd1;
      2'd2: coefficient = 2'd3;
      default: coefficient = 2'd1;
    endcase
  end

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg start;
  wire busy;
  wire done;
  wire [11:0] result;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .start(start),
    .busy(busy),
    .done(done),
    .result(result)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  initial begin
    rst_n = 1'b0;
    start = 1'b0;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    @(negedge clk);
    start = 1'b1;
    @(negedge clk);
    start = 1'b0;
    while (done !== 1'b1) begin
      @(posedge clk);
    end
    #1;
    if (busy !== 1'b0) begin
      $display("TEST_FAIL busy did not clear");
      $finish;
    end
    if (result !== 12'd17) begin
      $display("TEST_FAIL expected result=17 got %0d", result);
      $finish;
    end
    @(posedge clk);
    #1;
    if (done !== 1'b0) begin
      $display("TEST_FAIL done was not one cycle");
      $finish;
    end
    $display("TEST_PASS");
    $finish;
  end
  initial begin
    #100000;
    $display("TEST_FAIL timeout waiting for expected input/output behavior");
    $finish;
  end

endmodule

