module pwm_channel #(
    parameter WIDTH = 8
) (
    input wire [WIDTH-1:0] counter,
    input wire [WIDTH-1:0] duty,
    output wire pwm_out
);

  assign pwm_out = (counter < duty);

endmodule

module pwm_timer #(
    parameter WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    output reg [WIDTH-1:0] counter
);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      counter <= {WIDTH{1'b0}};
    end else begin
      counter <= counter + {{(WIDTH-1){1'b0}}, 1'b1};
    end
  end

endmodule

module top (
    input wire clk,
    input wire rst_n,
    input wire [7:0] duty,
    output wire pwm_out
);

  wire [7:0] counter;

  pwm_timer #(
    .WIDTH(8)
  ) u_pwm_timer (
    .clk(clk),
    .rst_n(rst_n),
    .counter(counter)
  );

  pwm_channel #(
    .WIDTH(8)
  ) u_pwm_channel (
    .counter(counter),
    .duty(duty),
    .pwm_out(pwm_out)
  );

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg [7:0] duty;
  wire pwm_out;
  integer high_count;
  integer i;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .duty(duty),
    .pwm_out(pwm_out)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  initial begin
    rst_n = 1'b0;
    duty = 8'd3;
    repeat (2) @(posedge clk);
    @(negedge clk);
    rst_n = 1'b1;

    high_count = 0;
    #1;
    if (pwm_out === 1'b1) begin
      high_count = high_count + 1;
    end
    for (i = 1; i < 8; i = i + 1) begin
      @(posedge clk);
      #1;
      if (pwm_out === 1'b1) begin
        high_count = high_count + 1;
      end
    end

    if (high_count != 3) begin
      $display("TEST_FAIL expected %0d high cycles got %0d", 3, high_count);
      $finish;
    end
    $display("TEST_PASS");
    $finish;
  end
  initial begin
    #100000;
    $display("TEST_FAIL timeout waiting for expected input/output behavior");
    $finish;
  end

endmodule

