module accumulator_core #(
    parameter WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    input wire sample_ready,
    input wire [WIDTH-1:0] sample,
    output wire [WIDTH+3:0] sum
);

  reg [WIDTH+3:0] sum_r;

  assign sum = sum_r + ((sample_valid && sample_ready) ? {{4{1'b0}}, sample} : {(WIDTH+4){1'b0}});

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      sum_r <= {(WIDTH+4){1'b0}};
    end else if (sample_valid && sample_ready) begin
      sum_r <= sum;
    end
  end

endmodule

module skid_buffer #(
    parameter WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [WIDTH-1:0] out_data
);

  reg valid_r;
  reg [WIDTH-1:0] data_r;

  assign in_ready = !valid_r || out_ready;
  assign out_valid = valid_r;
  assign out_data = data_r;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      valid_r <= 1'b0;
      data_r <= {WIDTH{1'b0}};
    end else if (in_ready) begin
      valid_r <= in_valid;
      if (in_valid) begin
        data_r <= in_data;
      end
    end
  end

endmodule

module stream_join #(
    parameter WIDTH = 8
) (
    input wire in0_valid,
    output wire in0_ready,
    input wire [WIDTH-1:0] in0_data,
    input wire in1_valid,
    output wire in1_ready,
    input wire [WIDTH-1:0] in1_data,
    output wire out_valid,
    input wire out_ready,
    output wire [WIDTH-1:0] out_data
);

  assign out_valid = in0_valid && in1_valid;
  assign in0_ready = out_ready && in1_valid;
  assign in1_ready = out_ready && in0_valid;
  assign out_data = in0_data + in1_data;

endmodule

module stream_stage #(
    parameter WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [WIDTH-1:0] in_data,
    output reg out_valid,
    input wire out_ready,
    output reg [WIDTH-1:0] out_data
);

  assign in_ready = !out_valid || out_ready;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      out_valid <= 1'b0;
      out_data <= {WIDTH{1'b0}};
    end else if (in_ready) begin
      out_valid <= in_valid;
      if (in_valid) begin
        out_data <= in_data;
      end
    end
  end

endmodule

module top (
    input wire clk,
    input wire rst_n,
    input wire in0_valid,
    output wire in0_ready,
    input wire [7:0] in0_data,
    input wire in1_valid,
    output wire in1_ready,
    input wire [7:0] in1_data,
    output wire out_valid,
    input wire out_ready,
    output wire [11:0] out_data
);

  wire s0_valid;
  wire s0_ready;
  wire [7:0] s0_data;
  wire s1_valid;
  wire s1_ready;
  wire [7:0] s1_data;
  wire joined_valid;
  wire [7:0] joined_data;
  wire accum_valid;
  wire accum_ready;
  wire [11:0] accum_sum;

  skid_buffer #(
    .WIDTH(8)
  ) u_skid0 (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(in0_valid),
    .in_ready(in0_ready),
    .in_data(in0_data),
    .out_valid(s0_valid),
    .out_ready(s0_ready),
    .out_data(s0_data)
  );

  skid_buffer #(
    .WIDTH(8)
  ) u_skid1 (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(in1_valid),
    .in_ready(in1_ready),
    .in_data(in1_data),
    .out_valid(s1_valid),
    .out_ready(s1_ready),
    .out_data(s1_data)
  );

  stream_join #(
    .WIDTH(8)
  ) u_stream_join (
    .in0_valid(s0_valid),
    .in0_ready(s0_ready),
    .in0_data(s0_data),
    .in1_valid(s1_valid),
    .in1_ready(s1_ready),
    .in1_data(s1_data),
    .out_valid(joined_valid),
    .out_ready(accum_ready),
    .out_data(joined_data)
  );

  accumulator_core #(
    .WIDTH(8)
  ) u_accumulator_core (
    .clk(clk),
    .rst_n(rst_n),
    .sample_valid(joined_valid),
    .sample_ready(accum_ready),
    .sample(joined_data),
    .sum(accum_sum)
  );

  assign accum_valid = joined_valid && accum_ready;

  stream_stage #(
    .WIDTH(12)
  ) u_stage (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(accum_valid),
    .in_ready(accum_ready),
    .in_data(accum_sum),
    .out_valid(out_valid),
    .out_ready(out_ready),
    .out_data(out_data)
  );

endmodule

