module axi_lite_read_ctrl (
    input wire clk,
    input wire rst_n,
    input wire arvalid,
    output wire arready,
    input wire [3:0] araddr,
    output reg rvalid,
    input wire rready,
    output wire read_valid,
    output wire [3:0] read_addr
);

  wire accept_read;

  assign arready = !rvalid;
  assign accept_read = arvalid && arready;
  assign read_valid = accept_read;
  assign read_addr = araddr;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rvalid <= 1'b0;
    end else begin
      if (accept_read) begin
        rvalid <= 1'b1;
      end else if (rvalid && rready) begin
        rvalid <= 1'b0;
      end
    end
  end

endmodule

module axi_lite_write_ctrl #(
    parameter DATA_WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire awvalid,
    output wire awready,
    input wire [3:0] awaddr,
    input wire wvalid,
    output wire wready,
    input wire [DATA_WIDTH-1:0] wdata,
    input wire wstrb,
    output reg bvalid,
    input wire bready,
    output wire write_valid,
    output wire [3:0] write_addr,
    output wire [DATA_WIDTH-1:0] write_data
);

  wire accept_write;

  assign awready = !bvalid;
  assign wready = !bvalid;
  assign accept_write = awvalid && wvalid && awready && wready && wstrb;
  assign write_valid = accept_write;
  assign write_addr = awaddr;
  assign write_data = wdata;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      bvalid <= 1'b0;
    end else begin
      if (accept_write) begin
        bvalid <= 1'b1;
      end else if (bvalid && bready) begin
        bvalid <= 1'b0;
      end
    end
  end

endmodule

module control_reg_bank #(
    parameter DATA_WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire write_valid,
    input wire [3:0] write_addr,
    input wire [DATA_WIDTH-1:0] write_data,
    input wire read_valid,
    input wire [3:0] read_addr,
    output reg [DATA_WIDTH-1:0] read_data,
    input wire stream_done,
    output reg start_pulse,
    output reg [DATA_WIDTH-1:0] sample0,
    output reg [DATA_WIDTH-1:0] sample1,
    output reg irq_state
);

  reg [DATA_WIDTH-1:0] ctrl;
  reg busy;
  reg done;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      ctrl <= {DATA_WIDTH{1'b0}};
      sample0 <= {DATA_WIDTH{1'b0}};
      sample1 <= {DATA_WIDTH{1'b0}};
      busy <= 1'b0;
      done <= 1'b0;
      irq_state <= 1'b0;
      start_pulse <= 1'b0;
      read_data <= {DATA_WIDTH{1'b0}};
    end else begin
      start_pulse <= 1'b0;
      if (write_valid) begin
        case (write_addr)
          4'h0: begin
            ctrl <= write_data;
            if (write_data[0]) begin
              start_pulse <= 1'b1;
              busy <= 1'b1;
              done <= 1'b0;
            end
            if (write_data[1]) begin
              irq_state <= 1'b0;
            end
          end
          4'h4: sample0 <= write_data;
          4'h8: sample1 <= write_data;
          default: ctrl <= ctrl;
        endcase
      end
      if (stream_done) begin
        busy <= 1'b0;
        done <= 1'b1;
        irq_state <= 1'b1;
      end
      if (read_valid) begin
        case (read_addr)
          4'h0: read_data <= ctrl;
          4'h4: read_data <= sample0;
          4'h8: read_data <= sample1;
          4'hc: read_data <= {{(DATA_WIDTH-3){1'b0}}, irq_state, done, busy};
          default: read_data <= {DATA_WIDTH{1'b0}};
        endcase
      end
    end
  end

endmodule

module irq_status (
    input wire irq_in,
    output wire irq_out
);

  assign irq_out = irq_in;

endmodule

module sample_stream_adapter #(
    parameter DATA_WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_WIDTH-1:0] sample0,
    input wire [DATA_WIDTH-1:0] sample1,
    output reg tvalid,
    input wire tready,
    output reg [(2*DATA_WIDTH)-1:0] tdata,
    output reg tlast,
    output reg stream_done
);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      tvalid <= 1'b0;
      tdata <= {(2*DATA_WIDTH){1'b0}};
      tlast <= 1'b0;
      stream_done <= 1'b0;
    end else begin
      stream_done <= 1'b0;
      if (start && !tvalid) begin
        tvalid <= 1'b1;
        tdata <= {sample1, sample0};
        tlast <= 1'b1;
      end else if (tvalid && tready) begin
        tvalid <= 1'b0;
        tlast <= 1'b0;
        stream_done <= 1'b1;
      end
    end
  end

endmodule

