module baud_tick_gen (
    input wire clk,
    input wire rst_n,
    input wire enable,
    output wire tick
);

  reg [1:0] div_count;

  assign tick = enable && (div_count == 2'd3);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      div_count <= 2'd0;
    end else if (enable) begin
      div_count <= div_count + 2'd1;
    end else begin
      div_count <= 2'd0;
    end
  end

endmodule

module uart_tx_core (
    input wire clk,
    input wire rst_n,
    input wire baud_tick,
    input wire start,
    input wire [7:0] data,
    output reg tx,
    output reg busy,
    output reg done
);

  localparam [1:0] IDLE = 2'd0;
  localparam [1:0] DATA = 2'd1;
  localparam [1:0] STOP = 2'd2;
  localparam [1:0] CLEANUP = 2'd3;

  reg [1:0] state;
  reg [2:0] bit_index;
  reg [7:0] shifter;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      bit_index <= 3'd0;
      shifter <= 8'd0;
      tx <= 1'b1;
      busy <= 1'b0;
      done <= 1'b0;
    end else begin
      done <= 1'b0;
      case (state)
        IDLE: begin
          tx <= 1'b1;
          busy <= 1'b0;
          bit_index <= 3'd0;
          if (start) begin
            shifter <= data;
            tx <= 1'b0;
            busy <= 1'b1;
            state <= DATA;
          end
        end
        DATA: begin
          if (baud_tick) begin
            tx <= shifter[0];
            shifter <= {1'b0, shifter[7:1]};
            if (bit_index == 3'd7) begin
              bit_index <= 3'd0;
              state <= STOP;
            end else begin
              bit_index <= bit_index + 3'd1;
            end
          end
        end
        STOP: begin
          if (baud_tick) begin
            tx <= 1'b1;
            state <= CLEANUP;
          end
        end
        CLEANUP: begin
          if (baud_tick) begin
            tx <= 1'b1;
            busy <= 1'b0;
            done <= 1'b1;
            state <= IDLE;
          end
        end
        default: begin
          state <= IDLE;
          tx <= 1'b1;
          busy <= 1'b0;
        end
      endcase
    end
  end

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg start;
  reg [7:0] data;
  wire tx;
  wire busy;
  wire done;
  reg [7:0] expected_bits;
  integer i;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .start(start),
    .data(data),
    .tx(tx),
    .busy(busy),
    .done(done)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  initial begin
    rst_n = 1'b0;
    start = 1'b0;
    data = 8'd0;
    expected_bits = 8'hA5;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    @(negedge clk);
    data = 8'hA5;
    start = 1'b1;
    @(negedge clk);
    start = 1'b0;
    #1;
    if (tx !== 1'b0) begin
      $display("TEST_FAIL start bit expected 0 got %0b", tx);
      $finish;
    end
    if (busy !== 1'b1) begin
      $display("TEST_FAIL busy was not asserted");
      $finish;
    end

    for (i = 0; i < 8; i = i + 1) begin
      repeat (4) @(posedge clk);
      #1;
      if (tx !== expected_bits[i]) begin
        $display(
          "TEST_FAIL data bit %0d expected %0b got %0b",
          i,
          expected_bits[i],
          tx
        );
        $finish;
      end
    end

    repeat (4) @(posedge clk);
    #1;
    if (tx !== 1'b1) begin
      $display("TEST_FAIL stop bit expected 1 got %0b", tx);
      $finish;
    end

    repeat (4) @(posedge clk);
    #1;
    if (done !== 1'b1) begin
      $display("TEST_FAIL done was not asserted");
      $finish;
    end
    if (busy !== 1'b0) begin
      $display("TEST_FAIL busy did not clear");
      $finish;
    end
    @(posedge clk);
    #1;
    if (done !== 1'b0) begin
      $display("TEST_FAIL done was not one cycle");
      $finish;
    end

    $display("TEST_PASS");
    $finish;
  end
  initial begin
    #100000;
    $display("TEST_FAIL timeout waiting for expected input/output behavior");
    $finish;
  end

endmodule

